    ) -> Result<ExecuteCommandResponse, GrpcClientError> {
        let ok = self.netmaker_restart("netclient").await?;
        Ok(ExecuteCommandResponse {
            success: ok,
            exit_code: if ok { 0 } else { 1 },
            stdout: String::new(),
            stderr: String::new(),
        })
    }

    async fn netclient_noargs(
        &self,
        command: ExecuteNetclientCommand,
    ) -> Result<ExecuteCommandResponse, GrpcClientError> {
        let mut client = self.pool.netmaker_client(&self.netmaker_address).await?;
        let response = client
            .execute_command(authenticated_netmaker_request!(ExecuteCommandRequest {
                command: Some(command),
            }))
            .await
            .map_err(|e| GrpcClientError::RequestFailed(e.to_string()))?;
        Ok(response.into_inner())
    }
}

