//! Rtnetlink helpers - native netlink operations for IP addresses and routes

use anyhow::{Context, Result};
use futures::TryStreamExt;
use netlink_packet_route::address::AddressAttribute;
use netlink_packet_route::link::LinkAttribute;
use rtnetlink::{new_connection, IpVersion};
use serde::{Deserialize, Serialize};
use std::fs::File;
use std::future::Future;
use std::net::Ipv4Addr;
use std::os::fd::AsRawFd;
use tokio::sync::oneshot;

/// Network interface information
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NetworkInterface {
    pub name: String,
    pub index: u32,
    pub mac_address: Option<String>,
    pub mtu: Option<u32>,
    pub flags: Vec<String>,
    pub state: String,
    pub kind: Option<String>,
    pub addresses: Vec<InterfaceAddress>,
}

/// IP address on an interface
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InterfaceAddress {
    pub address: String,
    pub prefix_len: u8,
    pub family: String,
}

/// Execute one asynchronous rtnetlink transaction in a target network
/// namespace on a dedicated OS thread.
///
/// Network namespace membership is thread-scoped.  The operation closure is
/// invoked only after `setns(CLONE_NEWNET)`, so any netlink sockets it creates
/// belong to the target namespace.  No shared Tokio runtime worker ever enters
/// the target namespace.
pub async fn in_network_namespace<T, F, Fut>(netns_pid: u32, operation: F) -> Result<T>
where
    T: Send + 'static,
    F: FnOnce() -> Fut + Send + 'static,
    Fut: Future<Output = Result<T>> + 'static,
{
    if netns_pid == 0 {
        anyhow::bail!("network namespace PID must be greater than zero");
    }

    let (tx, rx) = oneshot::channel();
    std::thread::Builder::new()
        .name(format!("rtnetlink-netns-{netns_pid}"))
        .spawn(move || {
            let result = (|| -> Result<T> {
                let original =
                    File::open("/proc/self/ns/net").context("open current network namespace")?;
                let target_path = format!("/proc/{netns_pid}/ns/net");
                let target = File::open(&target_path)
                    .with_context(|| format!("open target network namespace {target_path}"))?;

                set_network_namespace(&target)
                    .with_context(|| format!("enter network namespace for PID {netns_pid}"))?;

                let runtime = tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .context("build dedicated rtnetlink runtime")?;
                let operation_result = runtime.block_on(operation());
                drop(runtime);

                let restore_result =
                    set_network_namespace(&original).context("restore original network namespace");
                match (operation_result, restore_result) {
                    (Ok(value), Ok(())) => Ok(value),
                    (Err(error), Ok(())) => Err(error),
                    (Ok(_), Err(error)) => Err(error),
                    (Err(operation_error), Err(restore_error)) => Err(anyhow::anyhow!(
                        "network namespace operation failed: {operation_error:#}; \
                         restoring original namespace also failed: {restore_error:#}"
                    )),
                }
            })();
            let _ = tx.send(result);
        })
        .context("spawn dedicated network namespace thread")?;

    rx.await
        .context("dedicated network namespace thread terminated without a result")?
}

fn set_network_namespace(namespace: &File) -> Result<()> {
    // SAFETY: `namespace` is an open `/proc/*/ns/net` descriptor. setns only
    // affects this dedicated thread, and callers restore the original
    // namespace before the thread returns.
    let rc = unsafe { libc::setns(namespace.as_raw_fd(), libc::CLONE_NEWNET) };
    if rc == 0 {
        Ok(())
    } else {
        Err(std::io::Error::last_os_error()).context("setns(CLONE_NEWNET)")
    }
}

/// List all network interfaces with their details
pub async fn list_interfaces() -> Result<Vec<NetworkInterface>> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    let mut interfaces = Vec::new();
    let mut links = handle.link().get().execute();

    while let Some(link) = links.try_next().await? {
        let index = link.header.index;
        let mut name = String::new();
        let mut mac_address = None;
        let mut mtu = None;
        let mut kind = None;

        // Extract attributes
        for attr in &link.attributes {
            match attr {
                LinkAttribute::IfName(n) => name = n.clone(),
                LinkAttribute::Address(addr) => {
                    mac_address = Some(
                        addr.iter()
                            .map(|b| format!("{:02x}", b))
                            .collect::<Vec<_>>()
                            .join(":"),
                    );
                }
                LinkAttribute::Mtu(m) => mtu = Some(*m),
                LinkAttribute::LinkInfo(infos) => {
                    for info in infos {
                        if let netlink_packet_route::link::LinkInfo::Kind(k) = info {
                            kind = Some(format!("{:?}", k));
                        }
                    }
                }
                _ => {}
            }
        }

        // Determine state from flags
        let flags_val = &link.header.flags;
        let flags: Vec<String> = flags_val.iter().map(|f| format!("{:?}", f)).collect();
        let is_up = flags_val
            .iter()
            .any(|f| matches!(f, netlink_packet_route::link::LinkFlag::Up));
        let state = if is_up {
            "up".to_string()
        } else {
            "down".to_string()
        };

        // Get addresses for this interface
        let addresses = match get_interface_addresses(&handle, index).await {
            Ok(addrs) => addrs,
            Err(e) => {
                log::warn!("Failed to get addresses for interface {}: {}", name, e);
                Vec::new()
            }
        };

        interfaces.push(NetworkInterface {
            name,
            index,
            mac_address,
            mtu,
            flags,
            state,
            kind,
            addresses,
        });
    }

    Ok(interfaces)
}

/// Get addresses for a specific interface
async fn get_interface_addresses(
    handle: &rtnetlink::Handle,
    ifindex: u32,
) -> Result<Vec<InterfaceAddress>> {
    let mut addresses = Vec::new();
    let mut addr_stream = handle
        .address()
        .get()
        .set_link_index_filter(ifindex)
        .execute();

    while let Some(addr_msg) = addr_stream.try_next().await? {
        let family = match addr_msg.header.family {
            netlink_packet_route::AddressFamily::Inet => "inet".to_string(),
            netlink_packet_route::AddressFamily::Inet6 => "inet6".to_string(),
            f => format!("{:?}", f),
        };

        for attr in &addr_msg.attributes {
            if let AddressAttribute::Address(addr) = attr {
                let addr_str = addr.to_string();

                addresses.push(InterfaceAddress {
                    address: addr_str,
                    prefix_len: addr_msg.header.prefix_len,
                    family: family.clone(),
                });
            }
        }
    }

    Ok(addresses)
}

/// Get default route information
pub async fn get_default_route() -> Result<Option<serde_json::Value>> {
    use netlink_packet_route::route::RouteAttribute;

    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    let mut routes = handle.route().get(IpVersion::V4).execute();

    while let Some(route) = routes.try_next().await? {
        // Check if this is a default route (destination 0.0.0.0/0)
        if route.header.destination_prefix_length == 0 {
            let mut gateway = None;
            let mut oif_index = None;

            for attr in &route.attributes {
                match attr {
                    RouteAttribute::Gateway(gw) => {
                        gateway = Some(format!("{:?}", gw));
                    }
                    RouteAttribute::Oif(idx) => {
                        oif_index = Some(idx);
                    }
                    _ => {}
                }
            }

            // Try to get interface name for the output interface
            let mut oif_name = None;
            if let Some(idx) = oif_index {
                let mut links = handle.link().get().match_index(*idx).execute();
                if let Some(link) = links.try_next().await? {
                    for attr in &link.attributes {
                        if let LinkAttribute::IfName(name) = attr {
                            oif_name = Some(name.clone());
                            break;
                        }
                    }
                }
            }

            return Ok(Some(serde_json::json!({
                "gateway": gateway,
                "interface_index": oif_index,
                "interface_name": oif_name,
                "destination": "0.0.0.0/0",
            })));
        }
    }

    Ok(None)
}

