    while let Some(route) = routes.try_next().await? {
        // Check if this is a default route (destination 0.0.0.0/0)
        if route.header.destination_prefix_length == 0 {
            // Delete this route
            if let Err(e) = handle.route().del(route).execute().await {
                log::warn!("Failed to delete default route: {}", e);
            }
        }
    }

    Ok(())
}

/// List IPv4 routes for a given interface (by name).
pub async fn list_routes_for_interface(ifname: &str) -> Result<Vec<serde_json::Value>> {
    use netlink_packet_route::route::{RouteAddress, RouteAttribute};

    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .with_context(|| format!("interface '{ifname}' not found"))?;

    let mut routes = handle.route().get(IpVersion::V4).execute();
    let mut result = Vec::new();
    while let Some(route) = routes.try_next().await? {
        let mut output_index = None;
        let mut destination = None;
        let mut gateway = None;
        let mut table = u32::from(route.header.table);
        for attribute in &route.attributes {
            match attribute {
                RouteAttribute::Oif(index) => output_index = Some(*index),
                RouteAttribute::Destination(RouteAddress::Inet(address)) => {
                    destination = Some(*address)
                }
                RouteAttribute::Gateway(RouteAddress::Inet(address)) => gateway = Some(*address),
                RouteAttribute::Table(value) => table = *value,
                _ => {}
            }
        }
        if output_index != Some(link.header.index) {
            continue;
        }
        let destination = destination.unwrap_or(Ipv4Addr::UNSPECIFIED);
        result.push(serde_json::json!({
            "destination": format!("{destination}/{}", route.header.destination_prefix_length),
            "gateway": gateway.map(|address| address.to_string()),
            "interface_name": ifname,
            "interface_index": link.header.index,
            "table": table,
        }));
    }
    Ok(result)
}

