/// Add an IPv4 route in the current namespace through native rtnetlink.
pub async fn add_ipv4_route(
    destination: &str,
    gateway: Option<&str>,
    ifname: &str,
    table: Option<u32>,
) -> Result<()> {
    let (destination_addr, prefix) = parse_ipv4_cidr(destination)?;
    let gateway = gateway
        .map(|value| value.parse::<Ipv4Addr>().context("invalid route gateway"))
        .transpose()?;

    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .with_context(|| format!("interface '{ifname}' not found"))?;

    let mut request = handle
        .route()
        .add()
        .v4()
        .destination_prefix(destination_addr, prefix)
        .output_interface(link.header.index);
    if let Some(gateway) = gateway {
        request = request.gateway(gateway);
    }
    if let Some(table) = table {
        request = request.table_id(table);
    }
    request
        .execute()
        .await
        .with_context(|| format!("add route {destination} via {gateway:?} dev {ifname}"))
}

pub async fn add_ipv4_route_in_netns(
    netns_pid: u32,
    destination: &str,
    gateway: Option<&str>,
    ifname: &str,
    table: Option<u32>,
) -> Result<()> {
    let destination = destination.to_string();
    let gateway = gateway.map(str::to_string);
    let ifname = ifname.to_string();
    in_network_namespace(netns_pid, move || async move {
        add_ipv4_route(&destination, gateway.as_deref(), &ifname, table).await
    })
    .await
}

pub fn parse_ipv4_cidr(value: &str) -> Result<(Ipv4Addr, u8)> {
    let (address, prefix) = value
        .split_once('/')
        .ok_or_else(|| anyhow::anyhow!("IPv4 route must use CIDR notation: {value}"))?;
    let address = address.parse().context("invalid IPv4 route destination")?;
    let prefix: u8 = prefix.parse().context("invalid IPv4 route prefix")?;
    if prefix > 32 {
        anyhow::bail!("IPv4 route prefix must be between 0 and 32: {prefix}");
    }
    Ok((address, prefix))
}

/// Delete one exact IPv4 route from the current namespace.
///
/// Only routes matching destination, optional gateway, output interface, and
/// table are removed. Unrelated routes, including every route in table 51820,
/// are left untouched unless that table is explicitly requested by the caller.
pub async fn delete_ipv4_route(
    destination: &str,
    gateway: Option<&str>,
    ifname: &str,
    table: Option<u32>,
) -> Result<usize> {
    use netlink_packet_route::route::{RouteAddress, RouteAttribute};

    let (destination_addr, prefix) = parse_ipv4_cidr(destination)?;
    let gateway = gateway
        .map(|value| value.parse::<Ipv4Addr>().context("invalid route gateway"))
        .transpose()?;
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .with_context(|| format!("interface '{ifname}' not found"))?;

    let mut routes = handle.route().get(IpVersion::V4).execute();
    let mut matches = Vec::new();
    while let Some(route) = routes.try_next().await? {
        let mut route_destination = None;
        let mut route_gateway = None;
        let mut output_index = None;
        let mut route_table = u32::from(route.header.table);
        for attribute in &route.attributes {
            match attribute {
                RouteAttribute::Destination(RouteAddress::Inet(address)) => {
                    route_destination = Some(*address)
                }
                RouteAttribute::Gateway(RouteAddress::Inet(address)) => {
                    route_gateway = Some(*address)
                }
                RouteAttribute::Oif(index) => output_index = Some(*index),
                RouteAttribute::Table(value) => route_table = *value,
                _ => {}
            }
        }
        if route.header.destination_prefix_length == prefix
            && route_destination.unwrap_or(Ipv4Addr::UNSPECIFIED) == destination_addr
            && route_gateway == gateway
            && output_index == Some(link.header.index)
            && table.is_none_or(|expected| route_table == expected)
        {
            matches.push(route);
        }
    }

    let count = matches.len();
    for route in matches {
        handle
            .route()
            .del(route)
            .execute()
            .await
            .with_context(|| format!("delete route {destination} via {gateway:?} dev {ifname}"))?;
    }
    Ok(count)
}

