/// Exact observable subset of one IPv4 policy-routing rule.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Ipv4PolicyRule {
    pub priority: Option<u32>,
    pub table: u32,
    pub action: String,
    pub fw_mark: Option<u32>,
    pub fw_mask: Option<u32>,
    pub source: Option<String>,
    pub input_interface: Option<String>,
    pub output_interface: Option<String>,
}

fn policy_rule_view(rule: &netlink_packet_route::rule::RuleMessage) -> Ipv4PolicyRule {
    use netlink_packet_route::rule::RuleAttribute;

    let mut view = Ipv4PolicyRule {
        priority: None,
        table: u32::from(rule.header.table),
        action: format!("{:?}", rule.header.action),
        fw_mark: None,
        fw_mask: None,
        source: None,
        input_interface: None,
        output_interface: None,
    };
    for attribute in &rule.attributes {
        match attribute {
            RuleAttribute::Priority(value) => view.priority = Some(*value),
            RuleAttribute::Table(value) => view.table = *value,
            RuleAttribute::FwMark(value) => view.fw_mark = Some(*value),
            RuleAttribute::FwMask(value) => view.fw_mask = Some(*value),
            RuleAttribute::Source(std::net::IpAddr::V4(address)) => {
                view.source = Some(format!("{address}/{}", rule.header.src_len));
            }
            RuleAttribute::Iifname(value) => view.input_interface = Some(value.clone()),
            RuleAttribute::Oifname(value) => view.output_interface = Some(value.clone()),
            _ => {}
        }
    }
    view
}

pub async fn list_ipv4_policy_rules() -> Result<Vec<Ipv4PolicyRule>> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let mut rules = handle.rule().get(IpVersion::V4).execute();
    let mut result = Vec::new();
    while let Some(rule) = rules.try_next().await? {
        result.push(policy_rule_view(&rule));
    }
    Ok(result)
}

fn is_feature_fwmark_rule(rule: &Ipv4PolicyRule) -> bool {
    rule.priority == Some(10518)
        && rule.table == 51820
        && rule.action == "ToTable"
        && rule.fw_mark == Some(0x51821)
        && rule.fw_mask == Some(u32::MAX)
        && rule.source.is_none()
        && rule.input_interface.is_none()
        && rule.output_interface.is_none()
}

fn is_feature_blackhole_rule(rule: &Ipv4PolicyRule) -> bool {
    rule.priority == Some(10519)
        && rule.action == "Blackhole"
        && rule.fw_mark.is_none()
        && rule.source.as_deref() == Some("10.200.1.1/32")
        && rule.input_interface.is_none()
        && rule.output_interface.is_none()
}

async fn feature_rule_messages(
    handle: &rtnetlink::Handle,
) -> Result<Vec<netlink_packet_route::rule::RuleMessage>> {
    use netlink_packet_route::rule::RuleAttribute;

    let mut rules = handle.rule().get(IpVersion::V4).execute();
    let mut result = Vec::new();
    while let Some(rule) = rules.try_next().await? {
        let priority = rule
            .attributes
            .iter()
            .find_map(|attribute| match attribute {
                RuleAttribute::Priority(value) => Some(*value),
                _ => None,
            });
        if matches!(priority, Some(10518 | 10519)) {
            result.push(rule);
        }
    }
    Ok(result)
}

/// Ensure the two feature-owned rules are present exactly once.
///
/// Reconciliation may delete only priorities 10518 and 10519. It never adds,
/// deletes, flushes, or replaces routes in the externally owned table 51820.
pub async fn reconcile_netmk_policy_rules() -> Result<bool> {
    use netlink_packet_route::rule::{RuleAction, RuleAttribute};

    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let existing = feature_rule_messages(&handle).await?;
    let views: Vec<_> = existing.iter().map(policy_rule_view).collect();
    let fwmark_exact = views
        .iter()
        .filter(|rule| is_feature_fwmark_rule(rule))
        .count()
        == 1
        && views
            .iter()
            .filter(|rule| rule.priority == Some(10518))
            .count()
            == 1;
    let blackhole_exact = views
        .iter()
        .filter(|rule| is_feature_blackhole_rule(rule))
        .count()
        == 1
        && views
            .iter()
            .filter(|rule| rule.priority == Some(10519))
            .count()
            == 1;
    if fwmark_exact && blackhole_exact {
        return Ok(false);
    }

    for rule in existing {
        handle.rule().del(rule).execute().await?;
    }

    let mut fwmark = handle
        .rule()
        .add()
        .v4()
        .table_id(51820)
        .priority(10518)
        .fw_mark(0x51821)
        .action(RuleAction::ToTable);
    fwmark
        .message_mut()
        .attributes
        .push(RuleAttribute::FwMask(u32::MAX));
    fwmark
        .execute()
        .await
        .context("add priority 10518 fwmark 0x51821/0xffffffff lookup table 51820")?;

    handle
        .rule()
        .add()
        .v4()
        .table_id(0)
        .priority(10519)
        .source_prefix(Ipv4Addr::new(10, 200, 1, 1), 32)
        .action(RuleAction::Blackhole)
        .execute()
        .await
        .context("add priority 10519 source 10.200.1.1/32 blackhole")?;
    Ok(true)
}

pub async fn verify_netmk_policy_rules() -> Result<bool> {
    let rules = list_ipv4_policy_rules().await?;
    Ok(rules
        .iter()
        .filter(|rule| is_feature_fwmark_rule(rule))
        .count()
        == 1
        && rules
            .iter()
            .filter(|rule| rule.priority == Some(10518))
            .count()
            == 1
        && rules
            .iter()
            .filter(|rule| is_feature_blackhole_rule(rule))
            .count()
            == 1
        && rules
            .iter()
            .filter(|rule| rule.priority == Some(10519))
            .count()
            == 1)
}

/// Remove only the feature-owned policy priorities.
pub async fn delete_netmk_policy_rules() -> Result<usize> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let rules = feature_rule_messages(&handle).await?;
    let count = rules.len();
    for rule in rules {
        handle.rule().del(rule).execute().await?;
    }
    Ok(count)
}

