//! OpenFlow 1.3 controller server (passive mode)
//!
//! Listens for OVS to connect (passive mode), performs the OF1.3 handshake,
//! discovers port numbers by name via a PortDesc multipart request, clears all
//! existing flows, and installs the configured forwarding rules.
//!
//! Wire-protocol encoding is delegated to `rovs_openflow` types wherever
//! possible; the TCP listener and passive handshake are implemented here
//! because `rovs_openflow::VConn` only supports active (outbound) connections.

use anyhow::{Context, Result};
use bytes::Bytes;
use rovs_openflow::{
    ActionList, Flow, FlowStatsEntry, FlowStatsRequest, Match, Message, MessageType, OutputPort,
    Version,
};
use rovs_transport::Reconnect;
use std::collections::HashMap;
use std::net::SocketAddr;
use std::sync::{Arc, Mutex};
use std::time::Duration;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{mpsc, oneshot};

use crate::openflow_translate::{json_flow_to_add, json_flow_to_delete};

/// A request to install or delete a schema-driven flow on the currently
/// connected switch, submitted via `OpenFlowControllerHandle::send_flow`.
struct FlowRequest {
    flow_json: String,
    delete: bool,
    reply: oneshot::Sender<Result<String>>,
}

/// A command serviced by the task that owns the active switch TCP stream.
enum ControllerRequest {
    Mutate(FlowRequest),
    DumpSwitchFlows {
        reply: oneshot::Sender<Result<Vec<SwitchFlowStats>>>,
    },
}

/// One authoritative flow-table entry returned by the connected switch.
///
/// `matches` and `actions` are normalized, parsed OpenFlow representations;
/// counters come directly from the OF1.3 `OFPMP_FLOW` reply. This is distinct
/// from the controller's in-memory list of mutations it previously submitted.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize, PartialEq, Eq)]
pub struct SwitchFlowStats {
    pub table: u8,
    pub priority: u16,
    pub cookie: u64,
    pub matches: String,
    pub actions: String,
    pub packet_count: u64,
    pub byte_count: u64,
    pub idle_timeout: u16,
    pub hard_timeout: u16,
}

impl TryFrom<FlowStatsEntry> for SwitchFlowStats {
    type Error = anyhow::Error;

    fn try_from(entry: FlowStatsEntry) -> Result<Self> {
        let instructions = entry
            .decoded_instructions()
            .context("decoding flow-stat instructions")?;
        Ok(Self {
            table: entry.table_id,
            priority: entry.priority,
            cookie: entry.cookie,
            matches: entry.match_fields.to_string(),
            actions: instructions.to_string(),
            packet_count: entry.packet_count,
            byte_count: entry.byte_count,
            idle_timeout: entry.idle_timeout,
            hard_timeout: entry.hard_timeout,
        })
    }
}

// ── OF1.3 constants ────────────────────────────────────────────────────────────

/// Multipart type: port description.
const OFPMP_PORT_DESC: u16 = 13;
/// Multipart type: individual flow statistics.
const OFPMP_FLOW: u16 = 1;
/// "All" output port — used when out_port is not restricted.
const OFPP_ANY: u32 = 0xFFFF_FFFF;

// ── Wire helpers ──────────────────────────────────────────────────────────────

/// Build a raw OF1.3 message with an 8-byte header and `body`.
fn build_raw_msg(msg_type: MessageType, xid: u32, body: &[u8]) -> Vec<u8> {
    let msg = Message::new(Version::Of13, msg_type, xid, Bytes::copy_from_slice(body));
    msg.encode().to_vec()
}

/// Build an OF1.3 Hello message.
fn build_hello(xid: u32) -> Vec<u8> {
    build_raw_msg(MessageType::Hello, xid, &[])
}

/// Build an OF1.3 FeaturesRequest message.
fn build_features_request(xid: u32) -> Vec<u8> {
    build_raw_msg(MessageType::FeaturesRequest, xid, &[])
}

/// Build an OF1.3 PortDesc multipart request.
///
/// Body: type(2) + flags(2) + pad(4) = 8 bytes.
fn build_port_desc_request(xid: u32) -> Vec<u8> {
    let mut body = [0u8; 8];
    body[0..2].copy_from_slice(&OFPMP_PORT_DESC.to_be_bytes());
    build_raw_msg(MessageType::MultipartRequest, xid, &body)
}

/// Build an OF1.3 EchoReply that mirrors the request payload.
fn build_echo_reply(xid: u32, payload: &[u8]) -> Vec<u8> {
    build_raw_msg(MessageType::EchoReply, xid, payload)
}

/// Build an OF1.3 FlowMod DELETE ALL (wildcard match, all tables).
fn build_flow_mod_delete_all(xid: u32) -> Vec<u8> {
    let flow = Flow::delete();
    let msg = flow.to_message(Version::Of13, xid);
    msg.encode().to_vec()
}

/// Build an OF1.3 FlowMod ADD: match `in_port`, output to `out_port`.
pub fn build_flow_mod_add(in_port: u32, out_port: u32, priority: u16, xid: u32) -> Vec<u8> {
    let match_fields = Match::new().in_port(in_port);
    let actions = ActionList::new().output(OutputPort::Port(out_port));
    let flow = Flow::add()
        .priority(priority)
        .match_fields(match_fields)
        .actions(actions);
    let msg = flow.to_message(Version::Of13, xid);
    msg.encode().to_vec()
}

// ── Raw message receive ───────────────────────────────────────────────────────

/// A raw inbound OpenFlow message (header parsed, body buffered).
struct RawMsg {
    msg_type: u8,
    xid: u32,
    payload: Vec<u8>,
}

/// Read one complete OpenFlow message from `stream`.
async fn recv_msg(stream: &mut TcpStream) -> Result<RawMsg> {
    let mut hdr = [0u8; 8];
    stream
        .read_exact(&mut hdr)
        .await
        .context("reading OF header")?;

    let msg_type = hdr[1];
    let length = u16::from_be_bytes([hdr[2], hdr[3]]) as usize;
    let xid = u32::from_be_bytes([hdr[4], hdr[5], hdr[6], hdr[7]]);
    let payload_len = length.saturating_sub(8);

    let mut payload = vec![0u8; payload_len];
    if payload_len > 0 {
        stream
            .read_exact(&mut payload)
            .await
            .context("reading OF payload")?;
    }

    Ok(RawMsg {
        msg_type,
        xid,
        payload,
    })
}

/// Write raw bytes to `stream`.
async fn send_msg(stream: &mut TcpStream, bytes: &[u8]) -> Result<()> {
    stream.write_all(bytes).await.context("sending OF message")
}

// ── Port discovery ─────────────────────────────────────────────────────────────

/// Send a PortDesc request and parse all replies into `{port_name → ofport_no}`.
async fn discover_ports(stream: &mut TcpStream, xid: u32) -> Result<HashMap<String, u32>> {
    send_msg(stream, &build_port_desc_request(xid)).await?;

    let mut ports: HashMap<String, u32> = HashMap::new();

    loop {
        let msg = recv_msg(stream).await?;
        match msg.msg_type {
            // Echo request — must reply to stay alive during discovery.
            2 /* EchoRequest */ => {
                send_msg(stream, &build_echo_reply(msg.xid, &msg.payload)).await?;
            }
            // MultipartReply (19)
            19 => {
                if msg.payload.len() < 8 {
                    break;
                }
                let reply_type = u16::from_be_bytes([msg.payload[0], msg.payload[1]]);
                let flags = u16::from_be_bytes([msg.payload[2], msg.payload[3]]);

                if reply_type == OFPMP_PORT_DESC {
                    // OF1.3 ofp_port = 64 bytes:
                    // port_no(4) pad(4) hw_addr(6) pad(2) name(16) config(4) state(4)
                    // curr(4) advertised(4) supported(4) peer(4) curr_speed(4) max_speed(4)
                    let body = &msg.payload[8..];
                    for chunk in body.chunks_exact(64) {
                        let port_no =
                            u32::from_be_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
                        let name = String::from_utf8_lossy(&chunk[16..32])
                            .trim_end_matches('\0')
                            .to_string();
                        if !name.is_empty() && port_no < OFPP_ANY {
                            ports.insert(name, port_no);
                        }
                    }
                    // bit 0 of flags = OFPMPF_REPLY_MORE
                    if flags & 1 == 0 {
                        break;
                    }
                } else {
                    break;
                }
            }
            _ => break,
        }
    }

    Ok(ports)
}

/// Parse one OF1.3 `OFPMP_FLOW` reply payload.
fn parse_flow_stats_reply(payload: &[u8]) -> Result<(Vec<SwitchFlowStats>, bool)> {
    if payload.len() < 8 {
        anyhow::bail!("flow-stats multipart reply is shorter than its 8-byte header");
    }
    let reply_type = u16::from_be_bytes([payload[0], payload[1]]);
    if reply_type != OFPMP_FLOW {
        anyhow::bail!("expected OFPMP_FLOW reply, got multipart type {reply_type}");
    }
    let flags = u16::from_be_bytes([payload[2], payload[3]]);
    let mut offset = 8;
    let mut flows = Vec::new();
    while offset < payload.len() {
        if payload.len() - offset < FlowStatsEntry::FIXED_SIZE {
            anyhow::bail!(
                "truncated flow-stats entry at offset {offset}: {} bytes remain",
                payload.len() - offset
            );
        }
        let (entry, consumed) = FlowStatsEntry::decode(&payload[offset..])
            .context("decoding OF1.3 flow-stats entry")?;
        if consumed == 0 {
            anyhow::bail!("flow-stats decoder consumed zero bytes at offset {offset}");
        }
        flows.push(SwitchFlowStats::try_from(entry)?);
        offset += consumed;
    }
    Ok((flows, flags & 1 != 0))
}

/// Query the connected switch's logical OpenFlow table using OF1.3
/// `OFPMP_FLOW`, collecting all multipart replies with the request XID.
async fn query_switch_flows(stream: &mut TcpStream, xid: &mut u32) -> Result<Vec<SwitchFlowStats>> {
    let request_xid = *xid;
    *xid += 1;
    let request = FlowStatsRequest::new().to_message(Version::Of13, request_xid);
    send_msg(stream, &request.encode()).await?;

    let mut flows = Vec::new();
    loop {
        let msg = recv_msg(stream).await?;
        match msg.msg_type {
            2 /* EchoRequest */ => {
                send_msg(stream, &build_echo_reply(msg.xid, &msg.payload)).await?;
            }
            1 /* Error */ if msg.xid == request_xid => {
                anyhow::bail!(
                    "switch rejected OFPMP_FLOW request xid={request_xid}: {:02x?}",
                    msg.payload
                );
            }
            19 /* MultipartReply */ if msg.xid == request_xid => {
                let (mut entries, has_more) = parse_flow_stats_reply(&msg.payload)?;
                flows.append(&mut entries);
                if !has_more {
                    return Ok(flows);
                }
            }
            _ => {
                // Asynchronous PortStatus/FlowRemoved messages and replies for
                // other XIDs do not belong to this authoritative query.
            }
        }
    }
}

// ── Connection handler ────────────────────────────────────────────────────────

/// Handle one inbound OVS connection: handshake → port discovery → flow install → keepalive.
async fn handle_connection(
    mut stream: TcpStream,
    flows: Arc<Vec<(String, String, u16)>>,
    active_conn: Arc<Mutex<Option<mpsc::UnboundedSender<ControllerRequest>>>>,
) -> Result<()> {
    let mut xid: u32 = 1;

    // 1. Receive Hello from OVS.
    let hello = recv_msg(&mut stream).await?;
    if hello.msg_type != 0 {
        anyhow::bail!("expected Hello (type 0), got msg_type={}", hello.msg_type);
    }

    // 2. Send Hello.
    send_msg(&mut stream, &build_hello(xid)).await?;
    xid += 1;

    // 3. Send FeaturesRequest; wait for FeaturesReply (type 6), echo any pings.
    send_msg(&mut stream, &build_features_request(xid)).await?;
    xid += 1;

    loop {
        let msg = recv_msg(&mut stream).await?;
        match msg.msg_type {
            2 /* EchoRequest */ => {
                send_msg(&mut stream, &build_echo_reply(msg.xid, &msg.payload)).await?;
            }
            6 /* FeaturesReply */ => break,
            _ => {}
        }
    }

    // 4. Discover ports via PortDesc multipart.
    let port_map = discover_ports(&mut stream, xid).await?;
    xid += 1;

    log::info!(
        "OF controller: discovered {} ports: {:?}",
        port_map.len(),
        port_map.keys().collect::<Vec<_>>()
    );

    // 5. Delete all existing flows.
    send_msg(&mut stream, &build_flow_mod_delete_all(xid)).await?;
    xid += 1;

    // 6. Install configured flows.
    let mut installed = 0u32;
    for (in_name, out_name, priority) in flows.iter() {
        match (
            port_map.get(in_name.as_str()),
            port_map.get(out_name.as_str()),
        ) {
            (Some(&in_port), Some(&out_port)) => {
                send_msg(
                    &mut stream,
                    &build_flow_mod_add(in_port, out_port, *priority, xid),
                )
                .await?;
                xid += 1;
                installed += 1;
                log::info!(
                    "OF controller: installed flow {} (port {}) → {} (port {}), priority={}",
                    in_name,
                    in_port,
                    out_name,
                    out_port,
                    priority
                );
            }
            _ => {
                log::warn!(
                    "OF controller: port not found for flow {} → {} (known: {:?})",
                    in_name,
                    out_name,
                    port_map.keys().collect::<Vec<_>>()
                );
            }
        }
    }

    log::info!(
        "OF controller: {} flows installed; entering keepalive loop",
        installed
    );

    // 7. Register this connection's command channel so
    // `OpenFlowControllerHandle::send_flow` can reach the live switch, then
    // keepalive: reply to Echo requests and service schema-driven flow
    // requests for as long as this connection lasts.
    let (cmd_tx, mut cmd_rx) = mpsc::unbounded_channel::<ControllerRequest>();
    *active_conn.lock().unwrap() = Some(cmd_tx);

    let result = loop {
        tokio::select! {
            msg = recv_msg(&mut stream) => {
                match msg {
                    Ok(msg) if msg.msg_type == 2 /* EchoRequest */ => {
                        if let Err(e) = send_msg(&mut stream, &build_echo_reply(msg.xid, &msg.payload)).await {
                            break Err(e);
                        }
                    }
                    Ok(_) => {}
                    Err(e) => break Err(e),
                }
            }
            Some(command) = cmd_rx.recv() => {
                match command {
                    ControllerRequest::Mutate(req) => {
                        let outcome = if req.delete {
                            push_flow_delete(&mut stream, &req.flow_json, &port_map, &mut xid).await
                        } else {
                            push_flow_add(&mut stream, &req.flow_json, &port_map, &mut xid).await
                        };
                        let _ = req.reply.send(outcome);
                    }
                    ControllerRequest::DumpSwitchFlows { reply } => {
                        let _ = reply.send(query_switch_flows(&mut stream, &mut xid).await);
                    }
                }
            }
        }
    };

    *active_conn.lock().unwrap() = None;
    result
}

/// Translate and push one schema-driven flow ADD to the connected switch.
async fn push_flow_add(
    stream: &mut TcpStream,
    flow_json: &str,
    port_map: &HashMap<String, u32>,
    xid: &mut u32,
) -> Result<String> {
    let flow = json_flow_to_add(flow_json, port_map)?;
    let msg = flow.to_message(Version::Of13, *xid);
    *xid += 1;
    send_msg(stream, &msg.encode().to_vec()).await?;
    Ok(serde_json::json!({"ok": true, "action": "add"}).to_string())
}

/// Translate and push one schema-driven flow DELETE to the connected switch.
async fn push_flow_delete(
    stream: &mut TcpStream,
    flow_json: &str,
    port_map: &HashMap<String, u32>,
    xid: &mut u32,
) -> Result<String> {
    let flow = json_flow_to_delete(flow_json, port_map)?;
    let msg = flow.to_message(Version::Of13, *xid);
    *xid += 1;
    send_msg(stream, &msg.encode().to_vec()).await?;
    Ok(serde_json::json!({"ok": true, "action": "delete"}).to_string())
}

// ── Public API ────────────────────────────────────────────────────────────────

/// OpenFlow 1.3 controller — accepts connections from OVS and installs flows.
///
/// OVS connects *to* the controller (not the other way around).
/// Configure OVS with: `ovs-vsctl set-controller ovsbr0 tcp:<listen_addr>`
pub struct OpenFlowController {
    listen_addr: SocketAddr,
    flows: Vec<(String, String, u16)>,
    active_conn: Arc<Mutex<Option<mpsc::UnboundedSender<ControllerRequest>>>>,
    installed_flows: Arc<Mutex<Vec<serde_json::Value>>>,
}

impl OpenFlowController {
    /// Create a new controller that will listen on `listen_addr`.
    pub fn new(listen_addr: SocketAddr) -> Self {
        Self {
            listen_addr,
            flows: Vec::new(),
            active_conn: Arc::new(Mutex::new(None)),
            installed_flows: Arc::new(Mutex::new(Vec::new())),
        }
    }

    /// Get a cloneable handle for pushing schema-driven flows while the
    /// controller runs. Must be called before `run()` consumes `self`.
    pub fn handle(&self) -> OpenFlowControllerHandle {
        OpenFlowControllerHandle {
            active_conn: self.active_conn.clone(),
            installed_flows: self.installed_flows.clone(),
        }
    }

    /// Add a bidirectional forwarding pair (installs two flows: A→B and B→A).
    pub fn add_port_pair(mut self, port_a: &str, port_b: &str, priority: u16) -> Self {
        self.flows
            .push((port_a.to_string(), port_b.to_string(), priority));
        self.flows
            .push((port_b.to_string(), port_a.to_string(), priority));
        self
    }

    /// Add a single directed flow (in_port → out_port).
    pub fn add_flow(mut self, in_port: &str, out_port: &str, priority: u16) -> Self {
        self.flows
            .push((in_port.to_string(), out_port.to_string(), priority));
        self
    }

    /// Run the controller — listens for OVS connections and re-programs flows on each reconnect.
    ///
    /// Each spawned connection handler maintains its own `Reconnect` state machine so
    /// that rapid repeated failures (e.g. OVS flapping) are logged with backoff information
    /// rather than silently spinning.
    pub async fn run(self) -> Result<()> {
        let listener = TcpListener::bind(self.listen_addr)
            .await
            .with_context(|| format!("binding OpenFlow controller on {}", self.listen_addr))?;

        log::info!("OpenFlow controller listening on {}", self.listen_addr);

        let flows = Arc::new(self.flows);
        let active_conn = self.active_conn;

        loop {
            let (stream, peer) = listener.accept().await?;
            let flows = flows.clone();
            let active_conn = active_conn.clone();
            log::info!("OpenFlow controller: OVS connected from {}", peer);

            tokio::spawn(async move {
                // Per-connection reconnection tracker.  OVS is the active side so
                // we don't drive the reconnect loop ourselves — we just record state
                // and log when failures come in rapidly so operators see backoff hints.
                let mut reconnect = Reconnect::new();
                reconnect.set_max_backoff(Duration::from_secs(30));
                reconnect.connecting();

                match handle_connection(stream, flows, active_conn).await {
                    Ok(()) => {
                        // Clean close — mark disconnected so next accept starts fresh.
                        reconnect.disconnected();
                        log::info!("OF controller: connection from {} closed cleanly", peer);
                    }
                    Err(e) => {
                        reconnect.disconnected();
                        reconnect.increase_backoff();
                        log::warn!(
                            "OF controller: connection from {} ended with error \
                             (next OVS reconnect backoff hint: {:?}): {:#}",
                            peer,
                            reconnect.current_backoff(),
                            e
                        );
                    }
                }
            });
        }
    }
}

/// A cloneable handle for pushing schema-driven flows to whichever switch is
/// currently connected to an `OpenFlowController`, obtained via
/// `OpenFlowController::handle()` before calling `run()`.
///
/// This is what backs the `org.opdbus.v1.plugins.openflow` D-Bus interface
/// exposed by the `op-of-controller` binary — the openflow plugin's
/// `install_flow`/`delete_flow`/`query_flows` call through it instead of the
/// old (broken, now-removed) `op-openvswitch-daemon` passthrough.
#[derive(Clone)]
pub struct OpenFlowControllerHandle {
    active_conn: Arc<Mutex<Option<mpsc::UnboundedSender<ControllerRequest>>>>,
    installed_flows: Arc<Mutex<Vec<serde_json::Value>>>,
}

impl OpenFlowControllerHandle {
    /// Install or delete one schema-driven `FlowEntry` (JSON, matching the
    /// openflow plugin's shape) on the currently connected switch.
    pub async fn send_flow(&self, flow_json: String, delete: bool) -> Result<String> {
        let value: serde_json::Value =
            serde_json::from_str(&flow_json).context("invalid flow JSON")?;

        let (tx, rx) = oneshot::channel();
        {
            let guard = self.active_conn.lock().unwrap();
            let sender = guard
                .as_ref()
                .context("no OVS switch currently connected to the OpenFlow controller")?;
            sender
                .send(ControllerRequest::Mutate(FlowRequest {
                    flow_json,
                    delete,
                    reply: tx,
                }))
                .map_err(|_| anyhow::anyhow!("controller connection task is no longer running"))?;
        }
        let result: Result<String> = rx.await.context("controller dropped the reply channel")?;
        let result = result?;

        let mut flows = self.installed_flows.lock().unwrap();
        flows.retain(|f| f != &value);
        if !delete {
            flows.push(value);
        }
        Ok(result)
    }

    /// Return the flows this handle believes are currently installed
    /// (tracked in-memory since they were pushed through `send_flow` —
    /// this is not a live re-query of the switch's flow table).
    pub fn dump_flows(&self) -> Vec<String> {
        self.installed_flows
            .lock()
            .unwrap()
            .iter()
            .map(|v| v.to_string())
            .collect()
    }

    /// Query the currently connected switch's authoritative logical flow
    /// table using an OF1.3 `OFPMP_FLOW` multipart exchange.
    pub async fn dump_switch_flows(&self) -> Result<Vec<SwitchFlowStats>> {
        let (tx, rx) = oneshot::channel();
        {
            let guard = self.active_conn.lock().unwrap();
            let sender = guard
                .as_ref()
                .context("no OVS switch currently connected to the OpenFlow controller")?;
            sender
                .send(ControllerRequest::DumpSwitchFlows { reply: tx })
                .map_err(|_| anyhow::anyhow!("controller connection task is no longer running"))?;
        }

        tokio::time::timeout(Duration::from_secs(10), rx)
            .await
            .context("timed out waiting for OFPMP_FLOW reply")?
            .context("controller dropped the switch-flow reply channel")?
    }
}

// ── Tests ─────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_flow_mod_add_length() {
        let msg = build_flow_mod_add(6, 7, 100, 1);
        let declared_len = u16::from_be_bytes([msg[2], msg[3]]) as usize;
        assert_eq!(declared_len, msg.len(), "declared length must match actual");
        // OF1.3 version byte
        assert_eq!(msg[0], 0x04);
        // FlowMod type = 14
        assert_eq!(msg[1], 14);
    }

    #[test]
    fn test_flow_mod_delete_all() {
        let msg = build_flow_mod_delete_all(1);
        let declared_len = u16::from_be_bytes([msg[2], msg[3]]) as usize;
        assert_eq!(declared_len, msg.len(), "declared length must match actual");
        assert_eq!(msg[0], 0x04); // OF1.3
        assert_eq!(msg[1], 14); // FlowMod
    }

    #[test]
    fn flow_stats_request_targets_all_tables() {
        let msg = FlowStatsRequest::new()
            .to_message(Version::Of13, 42)
            .encode();
        assert_eq!(msg[0], 0x04); // OF1.3
        assert_eq!(msg[1], 18); // MultipartRequest
        assert_eq!(&msg[8..10], &OFPMP_FLOW.to_be_bytes());
        assert_eq!(msg[16], 0xff); // all tables
    }

    #[test]
    fn parses_authoritative_flow_stats_with_actions_and_counters() {
        let match_bytes = Match::new().in_port(7).udp_dst(51820).encode();
        let instruction_bytes = rovs_openflow::InstructionList::new()
            .apply_actions(ActionList::new().normal())
            .encode();
        let entry_len = FlowStatsEntry::FIXED_SIZE + match_bytes.len() + instruction_bytes.len();
        let mut entry = vec![0u8; FlowStatsEntry::FIXED_SIZE];
        entry[0..2].copy_from_slice(&(entry_len as u16).to_be_bytes());
        entry[2] = 3;
        entry[12..14].copy_from_slice(&100u16.to_be_bytes());
        entry[24..32].copy_from_slice(&0x4e4d4b0000000002u64.to_be_bytes());
        entry[32..40].copy_from_slice(&11u64.to_be_bytes());
        entry[40..48].copy_from_slice(&900u64.to_be_bytes());
        entry.extend(match_bytes);
        entry.extend(instruction_bytes);

        let mut payload = vec![0u8; 8];
        payload[0..2].copy_from_slice(&OFPMP_FLOW.to_be_bytes());
        payload.extend(entry);

        let (flows, has_more) = parse_flow_stats_reply(&payload).unwrap();
        assert!(!has_more);
        assert_eq!(flows.len(), 1);
        assert_eq!(flows[0].table, 3);
        assert_eq!(flows[0].priority, 100);
        assert_eq!(flows[0].cookie, 0x4e4d4b0000000002);
        assert_eq!(flows[0].packet_count, 11);
        assert_eq!(flows[0].byte_count, 900);
        assert!(flows[0].matches.contains("in_port=7"));
        assert!(flows[0].matches.contains("udp_dst=51820"));
        assert_eq!(flows[0].actions, "NORMAL");
    }

    #[test]
    fn rejects_non_flow_multipart_reply() {
        let mut payload = vec![0u8; 8];
        payload[0..2].copy_from_slice(&OFPMP_PORT_DESC.to_be_bytes());
        assert!(parse_flow_stats_reply(&payload).is_err());
    }
}

//! Translates the `openflow` plugin's JSON `FlowEntry`/`FlowAction` schema
//! (see `op-plugins/src/state_plugins/openflow.rs`) into real `rovs_openflow`
//! wire types.
//!
//! This replaces the old `op-openvswitch-daemon::parse_json_flow`, which only
//! understood 3 of the ~15 match keys and 3 of the 8 action variants the
//! schema actually declares (everything else was silently dropped with a
//! `tracing::warn!`, producing wildcard-match flows instead of the intended
//! narrow ones). Unsupported fields here are a hard error instead — callers
//! must not install a flow that is looser than what was requested.

use anyhow::{bail, Context, Result};
use rovs_openflow::{nxm, ActionList, Flow, FlowCommand, Match, OutputPort};
use std::collections::HashMap;
use std::net::Ipv4Addr;

#[derive(serde::Deserialize)]
pub struct JsonFlowEntry {
    #[serde(default)]
    pub table: u8,
    pub priority: u16,
    #[serde(default)]
    pub match_fields: HashMap<String, String>,
    #[serde(default)]
    pub actions: Vec<JsonFlowAction>,
    pub cookie: Option<u64>,
    #[serde(default)]
    pub idle_timeout: u16,
    #[serde(default)]
    pub hard_timeout: u16,
}

#[derive(serde::Deserialize, Clone, Debug)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum JsonFlowAction {
    Output { port: String },
    LoadRegister { register: u8, value: u64 },
    Resubmit { table: u8 },
    SetField { field: String, value: String },
    Drop,
    Normal,
    Controller { max_len: Option<u16> },
    ArpResponder { mac: String, ip: String },
}

/// Resolve a port token: a bare port number, `LOCAL`, or a symbolic name
/// looked up in `port_map` (as discovered via the controller's own PortDesc
/// multipart request — no separate OVSDB round trip needed).
fn resolve_port(token: &str, port_map: &HashMap<String, u32>) -> Result<u32> {
    if let Ok(n) = token.parse::<u32>() {
        return Ok(n);
    }
    if token.eq_ignore_ascii_case("LOCAL") {
        return Ok(0xffff_fffe); // OFPP_LOCAL
    }
    port_map
        .get(token)
        .copied()
        .with_context(|| format!("unknown port name '{token}' (not in discovered port map)"))
}

fn parse_mac(s: &str) -> Result<[u8; 6]> {
    let mut out = [0u8; 6];
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() != 6 {
        bail!("invalid MAC address '{}'", s);
    }
    for (i, p) in parts.iter().enumerate() {
        out[i] = u8::from_str_radix(p, 16).with_context(|| format!("invalid MAC octet '{p}'"))?;
    }
    Ok(out)
}

fn mac_to_u64(mac: [u8; 6]) -> u64 {
    mac.iter().fold(0u64, |acc, &b| (acc << 8) | b as u64)
}

fn ip_to_u32(ip: Ipv4Addr) -> u32 {
    u32::from(ip)
}

fn parse_ipv4(s: &str) -> Result<Ipv4Addr> {
    s.parse::<Ipv4Addr>()
        .with_context(|| format!("invalid IPv4 address '{s}'"))
}

/// Parse `a.b.c.d` or `a.b.c.d/n` into (address, prefix_len). Bare addresses
/// are treated as /32 host matches.
fn parse_cidr(s: &str) -> Result<(Ipv4Addr, u8)> {
    match s.split_once('/') {
        Some((addr, prefix)) => {
            let addr = parse_ipv4(addr)?;
            let prefix: u8 = prefix
                .parse()
                .with_context(|| format!("invalid CIDR prefix in '{s}'"))?;
            Ok((addr, prefix))
        }
        None => Ok((parse_ipv4(s)?, 32)),
    }
}

/// Parse OVS `tcp_flags` syntax: either a raw `0xNNN` value or `+flag` tokens
/// (e.g. `+fin+psh+urg`). Only the "must be set" (`+`) form is used anywhere
/// in this codebase's flow generators.
fn parse_tcp_flags(s: &str) -> Result<u16> {
    if let Some(hex) = s.strip_prefix("0x") {
        return u16::from_str_radix(hex, 16).with_context(|| format!("invalid tcp_flags '{s}'"));
    }
    let mut flags = 0u16;
    for tok in s.split('+').filter(|t| !t.is_empty()) {
        flags |= match tok {
            "fin" => 0x001,
            "syn" => 0x002,
            "rst" => 0x004,
            "psh" => 0x008,
            "ack" => 0x010,
            "urg" => 0x020,
            "ece" => 0x040,
            "cwr" => 0x080,
            "ns" => 0x100,
            other => bail!("unknown tcp_flags token '+{}' in '{}'", other, s),
        };
    }
    Ok(flags)
}

/// Parse OVS `ct_state` syntax (e.g. `+est+trk`, `+inv+trk`) into (value, mask).
/// Only "must be set" flags are supported (matches this codebase's usage).
fn parse_ct_state(s: &str) -> Result<(u32, u32)> {
    let mut bits = 0u32;
    for tok in s.split('+').filter(|t| !t.is_empty()) {
        bits |= match tok {
            "new" => 0x01,
            "est" => 0x02,
            "rel" => 0x04,
            "rpl" => 0x08,
            "inv" => 0x10,
            "trk" => 0x20,
            "snat" => 0x40,
            "dnat" => 0x80,
            other => bail!("unknown ct_state token '+{}' in '{}'", other, s),
        };
    }
    Ok((bits, bits))
}

/// Translate `match_fields` into a `rovs_openflow::Match`.
///
/// Two passes: first detect protocol markers (`tcp`/`udp`/`icmp`/`icmp6`/
/// `arp`/`ip`) to establish `eth_type`/`ip_proto` context, since `HashMap`
/// iteration order can't be relied on to see e.g. `udp` before `tp_dst`.
fn parse_match(fields: &HashMap<String, String>, port_map: &HashMap<String, u32>) -> Result<Match> {
    let mut m = Match::new();
    let mut ip_proto: Option<u8> = None;
    let mut eth_type: Option<u16> = None;

    if fields.contains_key("arp") {
        eth_type = Some(0x0806);
    }
    if fields.contains_key("icmp6") {
        eth_type = Some(0x86dd);
        ip_proto = Some(58);
    }
    if fields.contains_key("ip") {
        eth_type = eth_type.or(Some(0x0800));
    }
    if fields.contains_key("tcp") {
        eth_type = eth_type.or(Some(0x0800));
        ip_proto = ip_proto.or(Some(6));
    }
    if fields.contains_key("udp") {
        eth_type = eth_type.or(Some(0x0800));
        ip_proto = ip_proto.or(Some(17));
    }
    if fields.contains_key("icmp") {
        eth_type = eth_type.or(Some(0x0800));
        ip_proto = ip_proto.or(Some(1));
    }
    if let Some(et) = eth_type {
        m = m.eth_type(et);
    }
    if let Some(p) = ip_proto {
        m = m.ip_proto(p);
    }

    for (k, v) in fields {
        m = match k.as_str() {
            "arp" | "ip" | "tcp" | "udp" | "icmp" | "icmp6" => m, // handled above
            "in_port" => m.in_port(resolve_port(v, port_map)?),
            "dl_type" => {
                let et = if let Some(hex) = v.strip_prefix("0x") {
                    u16::from_str_radix(hex, 16)
                        .with_context(|| format!("invalid dl_type '{v}'"))?
                } else {
                    v.parse()
                        .with_context(|| format!("invalid dl_type '{v}'"))?
                };
                m.eth_type(et)
            }
            "dl_vlan" => m.vlan_vid(
                v.parse()
                    .with_context(|| format!("invalid dl_vlan '{v}'"))?,
            ),
            "dl_src" => m.eth_src(parse_mac(v)?),
            "tcp_flags" => {
                let mut m2 = m;
                m2.tcp_flags = Some(parse_tcp_flags(v)?);
                m2
            }
            "tp_src" => {
                let port: u16 = v.parse().with_context(|| format!("invalid tp_src '{v}'"))?;
                match ip_proto {
                    Some(6) => m.tcp_src(port),
                    Some(17) => m.udp_src(port),
                    _ => bail!("tp_src requires a 'tcp' or 'udp' marker in match_fields"),
                }
            }
            "tp_dst" => {
                let port: u16 = v.parse().with_context(|| format!("invalid tp_dst '{v}'"))?;
                match ip_proto {
                    Some(6) => m.tcp_dst(port),
                    Some(17) => m.udp_dst(port),
                    _ => bail!("tp_dst requires a 'tcp' or 'udp' marker in match_fields"),
                }
            }
            "nw_src" => {
                let (addr, prefix) = parse_cidr(v)?;
                m.ipv4_src(addr, prefix)
            }
            "nw_dst" => {
                let (addr, prefix) = parse_cidr(v)?;
                m.ipv4_dst(addr, prefix)
            }
            "ct_state" => {
                let (state, mask) = parse_ct_state(v)?;
                m.ct_state_masked(state, mask)
            }
            other => bail!(
                "unsupported OpenFlow match field '{}'={:?} — no translation available \
                 (rovs-openflow's Match type has no equivalent field)",
                other,
                v
            ),
        };
    }
    Ok(m)
}

/// Translate `actions` into a `rovs_openflow::ActionList`.
///
/// `ip_proto` (established while parsing match_fields) disambiguates
/// protocol-relative `SetField` targets like `tp_dst`.
fn build_actions(
    actions: &[JsonFlowAction],
    port_map: &HashMap<String, u32>,
    ip_proto: Option<u8>,
) -> Result<ActionList> {
    let mut list = ActionList::new();
    for a in actions {
        list = match a {
            JsonFlowAction::Output { port } => {
                if port.eq_ignore_ascii_case("LOCAL") {
                    list.output(OutputPort::Local)
                } else if port.eq_ignore_ascii_case("NORMAL") {
                    list.output(OutputPort::Normal)
                } else if port.eq_ignore_ascii_case("FLOOD") {
                    list.output(OutputPort::Flood)
                } else if port.eq_ignore_ascii_case("ALL") {
                    list.output(OutputPort::All)
                } else if port.eq_ignore_ascii_case("IN_PORT") {
                    list.output(OutputPort::InPort)
                } else if port.eq_ignore_ascii_case("CONTROLLER") {
                    list.output(OutputPort::Controller)
                } else {
                    list.output(OutputPort::Port(resolve_port(port, port_map)?))
                }
            }
            JsonFlowAction::Drop => list.drop(),
            JsonFlowAction::Normal => list.normal(),
            JsonFlowAction::Controller { max_len } => list.controller(max_len.unwrap_or(128)),
            JsonFlowAction::Resubmit { table } => list.resubmit_table(*table),
            JsonFlowAction::LoadRegister { register, value } => {
                let field = match register {
                    0 => nxm::REG0,
                    1 => nxm::REG1,
                    2 => nxm::REG2,
                    other => bail!(
                        "unsupported register {} — rovs-openflow only exposes NXM_NX_REG0..REG2",
                        other
                    ),
                };
                list.load_field(field, 0, 32, *value)
            }
            JsonFlowAction::SetField { field, value } => match field.as_str() {
                "dl_dst" | "eth_dst" => list.set_eth_dst(parse_mac(value)?),
                "dl_src" | "eth_src" => list.set_eth_src(parse_mac(value)?),
                "dl_vlan" | "vlan_vid" => {
                    let vid: u16 = value
                        .parse()
                        .with_context(|| format!("invalid vlan_vid '{value}'"))?;
                    list.set_vlan_vid(vid)
                }
                "tun_id" | "tunnel_id" => {
                    let id: u64 = value
                        .parse()
                        .with_context(|| format!("invalid tunnel_id '{value}'"))?;
                    list.set_tunnel_id(id)
                }
                "tp_dst" => {
                    let port: u16 = value
                        .parse()
                        .with_context(|| format!("invalid tp_dst '{value}'"))?;
                    match ip_proto {
                        Some(6) => list.load_field(nxm::TCP_DST, 0, 16, port as u64),
                        Some(17) => list.load_field(nxm::UDP_DST, 0, 16, port as u64),
                        _ => bail!(
                            "SetField tp_dst requires a 'tcp' or 'udp' marker in match_fields"
                        ),
                    }
                }
                "tp_src" => {
                    let port: u16 = value
                        .parse()
                        .with_context(|| format!("invalid tp_src '{value}'"))?;
                    match ip_proto {
                        Some(6) => list.load_field(nxm::TCP_SRC, 0, 16, port as u64),
                        Some(17) => list.load_field(nxm::UDP_SRC, 0, 16, port as u64),
                        _ => bail!(
                            "SetField tp_src requires a 'tcp' or 'udp' marker in match_fields"
                        ),
                    }
                }
                other => bail!(
                    "unsupported SetField target '{}'={:?} — no NXM field available in rovs-openflow",
                    other,
                    value
                ),
            },
            JsonFlowAction::ArpResponder { mac, ip } => {
                let mac_bytes = parse_mac(mac)?;
                let ip_addr = parse_ipv4(ip)?;
                list
                    // dst mac := original src mac; src mac := our mac
                    .move_field(nxm::ETH_SRC, nxm::ETH_DST, 48, 0, 0)
                    .set_eth_src(mac_bytes)
                    // ARP reply
                    .set_arp_op(2)
                    // tha := original sha; sha := our mac
                    .move_field(nxm::ARP_SHA, nxm::ARP_THA, 48, 0, 0)
                    .set_arp_sha(mac_to_u64(mac_bytes))
                    // tpa := original spa; spa := our ip
                    .move_field(nxm::ARP_SPA, nxm::ARP_TPA, 32, 0, 0)
                    .set_arp_spa(ip_to_u32(ip_addr))
                    .in_port()
            }
        };
    }
    Ok(list)
}

/// Translate a JSON-encoded `FlowEntry` (the openflow plugin's schema shape)
/// into a `rovs_openflow::Flow` ADD, resolving symbolic port names via
/// `port_map` (as discovered from the switch's own PortDesc reply).
pub fn json_flow_to_add(flow_json: &str, port_map: &HashMap<String, u32>) -> Result<Flow> {
    let entry: JsonFlowEntry = serde_json::from_str(flow_json).context("invalid FlowEntry JSON")?;
    let m = parse_match(&entry.match_fields, port_map)?;
    let ip_proto = m.ip_proto;
    let actions = build_actions(&entry.actions, port_map, ip_proto)?;

    let mut flow = Flow::add()
        .priority(entry.priority)
        .match_fields(m)
        .actions(actions)
        .idle_timeout(entry.idle_timeout)
        .hard_timeout(entry.hard_timeout);
    if let Some(c) = entry.cookie {
        flow = flow.cookie(c);
    }
    Ok(flow)
}

/// Translate a JSON-encoded `FlowEntry` into `DELETE_STRICT` scoped by table,
/// priority, and match. When a cookie is supplied it is also matched exactly;
/// this is the path used by feature-cookie cleanup.
pub fn json_flow_to_delete(flow_json: &str, port_map: &HashMap<String, u32>) -> Result<Flow> {
    let entry: JsonFlowEntry = serde_json::from_str(flow_json).context("invalid FlowEntry JSON")?;
    let m = parse_match(&entry.match_fields, port_map)?;
    let mut flow = Flow::delete()
        .table(entry.table)
        .priority(entry.priority)
        .match_fields(m);
    flow.command = FlowCommand::DeleteStrict;
    if let Some(cookie) = entry.cookie {
        flow.cookie = cookie;
        flow.cookie_mask = u64::MAX;
    }
    Ok(flow)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn delete_is_strict_and_cookie_exact() {
        let flow = json_flow_to_delete(
            r#"{
                "table": 0,
                "priority": 50,
                "match_fields": {"in_port": "7"},
                "actions": [{"type": "drop"}],
                "cookie": 5642247248711352575
            }"#,
            &HashMap::new(),
        )
        .unwrap();
        assert_eq!(flow.command, FlowCommand::DeleteStrict);
        assert_eq!(flow.table_id, 0);
        assert_eq!(flow.priority, 50);
        assert_eq!(flow.cookie, 5642247248711352575);
        assert_eq!(flow.cookie_mask, u64::MAX);
    }

    #[test]
    fn delete_without_cookie_remains_strict() {
        let flow = json_flow_to_delete(
            r#"{
                "table": 3,
                "priority": 50,
                "match_fields": {"in_port": "7"},
                "actions": [{"type": "drop"}]
            }"#,
            &HashMap::new(),
        )
        .unwrap();
        assert_eq!(flow.command, FlowCommand::DeleteStrict);
        assert_eq!(flow.table_id, 3);
        assert_eq!(flow.priority, 50);
        assert_eq!(flow.cookie_mask, 0);
    }
}

//! OpenFlow 1.3 controller for ovsbr0
//!
//! Listens on OF_CONTROLLER_LISTEN (default 10.200.0.1:6653) for OVS to
//! connect, then installs bidirectional flows between the configured port pairs.
//!
//! Environment variables:
//!   OF_CONTROLLER_LISTEN   listen address (default: 10.200.0.1:6653)
//!   OF_FLOW_PAIRS          comma-separated port pairs, e.g. "grpc-bridge:ovsbr0-sock"
//!                          defaults to "grpc-bridge:ovsbr0-sock"
//!   OF_FLOW_PRIORITY       flow priority (default: 100)
//!
//! Also exposes `org.opdbus.v1.plugins.openflow` at
//! `/org/opdbus/v1/plugins/openflow` on the system bus so the `openflow`
//! plugin (crates/op-plugins/src/state_plugins/openflow.rs) can push
//! schema-driven flows to whichever switch is currently connected.

use std::net::SocketAddr;

use anyhow::{Context, Result};
use op_network::{OpenFlowController, OpenFlowControllerHandle};
use tracing::info;
use tracing_subscriber::EnvFilter;
use zbus::interface;

struct OpenFlowDbusService {
    handle: OpenFlowControllerHandle,
}

#[interface(name = "org.opdbus.v1.plugins.openflow")]
impl OpenFlowDbusService {
    /// Install a schema-driven flow (JSON-encoded `FlowEntry`).
    async fn send_flow(&self, flow_json: String) -> zbus::fdo::Result<String> {
        self.handle
            .send_flow(flow_json, false)
            .await
            .map_err(|e| zbus::fdo::Error::Failed(format!("{e:#}")))
    }

    /// Delete a schema-driven flow (JSON-encoded `FlowEntry`).
    async fn delete_flow(&self, flow_json: String) -> zbus::fdo::Result<String> {
        self.handle
            .send_flow(flow_json, true)
            .await
            .map_err(|e| zbus::fdo::Error::Failed(format!("{e:#}")))
    }

    /// Dump flows this controller has pushed. This is non-authoritative
    /// in-memory mutation history retained for diagnostics and compatibility.
    async fn dump_flows(&self) -> Vec<String> {
        self.handle.dump_flows()
    }

    /// Query the connected switch's authoritative logical flow table with an
    /// OF1.3 OFPMP_FLOW multipart request. Each item is a JSON-encoded
    /// `SwitchFlowStats` record with parsed matches/actions and live counters.
    async fn dump_switch_flows(&self) -> zbus::fdo::Result<Vec<String>> {
        self.handle
            .dump_switch_flows()
            .await
            .map_err(|e| zbus::fdo::Error::Failed(format!("{e:#}")))?
            .into_iter()
            .map(|flow| {
                serde_json::to_string(&flow)
                    .map_err(|e| zbus::fdo::Error::Failed(format!("serializing switch flow: {e}")))
            })
            .collect()
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("op_network=info".parse()?))
        .init();

    let listen: SocketAddr = std::env::var("OF_CONTROLLER_LISTEN")
        .unwrap_or_else(|_| "10.200.0.1:6653".to_string())
        .parse()
        .expect("OF_CONTROLLER_LISTEN must be a valid socket address");

    let pairs_env =
        std::env::var("OF_FLOW_PAIRS").unwrap_or_else(|_| "grpc-bridge:ovsbr0-sock".to_string());

    let priority: u16 = std::env::var("OF_FLOW_PRIORITY")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(100);

    let mut controller = OpenFlowController::new(listen);

    for pair in pairs_env.split(',') {
        let parts: Vec<&str> = pair.trim().splitn(2, ':').collect();
        if parts.len() != 2 {
            tracing::warn!("Ignoring malformed flow pair: {:?}", pair);
            continue;
        }
        info!(
            "Flow pair: {} ↔ {} (priority {})",
            parts[0], parts[1], priority
        );
        controller = controller.add_port_pair(parts[0], parts[1], priority);
    }

    let dbus_handle = controller.handle();
    let service = OpenFlowDbusService {
        handle: dbus_handle,
    };
    let _dbus_conn = zbus::connection::Builder::system()?
        .name("org.opdbus.v1.plugins.openflow")?
        .serve_at("/org/opdbus/v1/plugins/openflow", service)?
        .build()
        .await
        .context("registering org.opdbus.v1.plugins.openflow on the system bus")?;
    info!("org.opdbus.v1.plugins.openflow registered on the system bus");

    controller.run().await
}

//! Mutation Engine - The Authoritative Source for State and Schema DNA
//!
//! The Mutation Engine is the central coordinator that:
//! - Authoritatively routes all mutations (gRPC and D-Bus)
//! - Ensures all state changes are strictly recorded in the Event Chain (Audit Log)
//! - Broadcasts authoritative state changes to gRPC subscribers
//! - Directly manages authoritative RCP stores (OVSDB, NonNet, SQLite)

use anyhow::Context as _;
use async_trait::async_trait;
use serde_json;
use simd_json::prelude::{ValueAsContainer, ValueAsMutContainer, ValueAsScalar, ValueObjectAccess};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::{broadcast, OnceCell, RwLock, Semaphore};
use zbus::zvariant::OwnedValue as ZOwnedValue;
use zbus::{Connection, Proxy};

use base64::Engine;
use op_blockchain::{PluginFootprint, StreamingBlockchain};
use op_identity::{read_sled, write_sled_full};
use op_llm::chat::ChatManager;
use op_network::rovs_proxy::OvsdbDbusClient;
use op_plugins::state_plugins::blockchain_plugin::{
    AuditEventRecord, QueryEventsInput, QueryEventsOutput, VerifyChainInput, VerifyChainOutput,
};
use op_state_store::{ChainEvent, Decision, EventChain, MemoryStore, OperationType, StateStore};

/// Default on-disk location of the streaming blockchain that backs the durable
/// audit trail, when `$OPDBUS_BLOCKCHAIN_PATH` is unset. Matches
/// `blockchain_plugin::DEFAULT_BASE_PATH` so both read the same chain.
const DEFAULT_BLOCKCHAIN_PATH: &str = "/var/lib/opdbus/blockchain";

/// A state change projected from the authoritative system bus
#[derive(Debug, Clone)]
pub struct StateChange {
    pub change_id: String,
    pub event_id: u64,
    pub plugin_id: String,
    pub object_path: String,
    pub change_type: ChangeType,
    pub member_name: Option<String>,
    pub old_value: Option<simd_json::OwnedValue>,
    pub new_value: simd_json::OwnedValue,
    pub tags_touched: Vec<String>,
    pub event_hash: String,
    pub timestamp: chrono::DateTime<chrono::Utc>,
    pub actor_id: String,
    pub source: ChangeSource,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ChangeType {
    PropertySet,
    PropertyDelete,
    MethodCall,
    Signal,
    ObjectAdded,
    ObjectRemoved,
    SchemaMigration,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ChangeSource {
    DBus,
    Grpc,
    Internal,
}

pub struct MutationEngine {
    /// Authoritative Event Chain
    pub event_chain: Arc<RwLock<EventChain>>,
    /// Real-time change projection channel
    change_tx: broadcast::Sender<StateChange>,
    /// State cache for instant gRPC retrieval
    state_cache: Arc<RwLock<HashMap<String, simd_json::OwnedValue>>>,
    /// System D-Bus connection authority
    pub dbus_connection: Arc<OnceCell<Connection>>,
    /// Session bus connection for projection tree introspection
    session_bus: Arc<OnceCell<Connection>>,
    /// Session bus connection with registered PluginV1 interfaces for signal emission.
    /// Set after SchemaRouter registers objects (server.rs spawned task).
    signal_bus: Arc<OnceCell<Connection>>,
    /// Resource limiter for D-Bus operations
    #[allow(dead_code)]
    dbus_call_limiter: Arc<Semaphore>,

    /// Durable audit sink: the streaming blockchain's `timing_subvol` holds one
    /// JSON record per event chain event, so the trail survives a restart.
    /// Empty until [`MutationEngine::init_audit_durability`] runs; a missing
    /// sink degrades to RAM-only recording rather than failing dispatches.
    audit_sink: Arc<OnceCell<Arc<StreamingBlockchain>>>,

    /// Authoritative RCP stores
    pub ovsdb: Arc<OvsdbDbusClient>,
    /// In-process plugin handles for MethodCall dispatch (e.g. createunixsocket).
    pub unix_socket: Arc<op_plugins::state_plugins::UnixSocketPlugin>,
    /// Provider runtime used only after ZeroClaw resolves a schema-declared route.
    chat_manager: Arc<ChatManager>,
}

impl std::fmt::Debug for MutationEngine {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("MutationEngine").finish()
    }
}

#[async_trait]
impl op_core::state_publisher::StatePublisher for MutationEngine {
    async fn publish_change(
        &self,
        plugin_id: String,
        path: String,
        change_type: op_core::state_publisher::ChangeType,
        property: Option<String>,
        old_value: Option<simd_json::OwnedValue>,
        new_value: simd_json::OwnedValue,
        tags: Vec<String>,
        source: String,
    ) -> anyhow::Result<()> {
        let internal_type = match change_type {
            op_core::state_publisher::ChangeType::PropertySet => ChangeType::PropertySet,
            op_core::state_publisher::ChangeType::Signal => ChangeType::Signal,
            op_core::state_publisher::ChangeType::Deleted => ChangeType::ObjectRemoved,
        };

        self.process_authoritative_change(
            plugin_id,
            path,
            internal_type,
            property,
            old_value,
            new_value,
            tags,
            source,
            None,
            ChangeSource::Internal,
        )
        .await
        .map(|_| ())
        .map_err(|e| anyhow::anyhow!(e))
    }
}

impl MutationEngine {
    /// Create a new authoritative Mutation Engine
    pub fn new(event_chain: Arc<RwLock<EventChain>>, ovsdb: Arc<OvsdbDbusClient>) -> Self {
        let (change_tx, _) = broadcast::channel(1024);
        Self {
            event_chain,
            change_tx,
            state_cache: Arc::new(RwLock::new(HashMap::new())),
            dbus_connection: Arc::new(OnceCell::new()),
            session_bus: Arc::new(OnceCell::new()),
            signal_bus: Arc::new(OnceCell::new()),
            dbus_call_limiter: Arc::new(Semaphore::new(32)),
            audit_sink: Arc::new(OnceCell::new()),
            ovsdb,
            unix_socket: Arc::new(op_plugins::state_plugins::UnixSocketPlugin::new()),
            chat_manager: Arc::new(ChatManager::new()),
        }
    }

    /// Open the durable audit sink and rebuild the in-memory event chain from it.
    ///
    /// Called once at startup (before the gRPC/D-Bus surfaces accept traffic) so
    /// that a query issued immediately after a restart sees the pre-restart
    /// history. Idempotent: the sink is behind a `OnceCell`, and the rebuild is
    /// skipped when the chain already holds events.
    ///
    /// Returns the number of events replayed from disk. A sink that cannot be
    /// opened (no Btrfs, no permission, path absent) is not an error: the engine
    /// keeps recording to RAM and logs at `warn!`.
    ///
    /// OSCAL subid: `src.service.event-chain.rebuild@v1`
    pub async fn init_audit_durability(&self) -> usize {
        let base_path = std::env::var("OPDBUS_BLOCKCHAIN_PATH")
            .unwrap_or_else(|_| DEFAULT_BLOCKCHAIN_PATH.to_string());
        self.init_audit_durability_at(&base_path).await
    }

    /// [`init_audit_durability`](Self::init_audit_durability) against an explicit
    /// chain path, bypassing `$OPDBUS_BLOCKCHAIN_PATH`.
    pub async fn init_audit_durability_at(&self, base_path: &str) -> usize {
        if self.audit_sink.get().is_some() {
            return 0;
        }

        let chain_store = match StreamingBlockchain::new(base_path).await {
            Ok(chain) => Arc::new(chain),
            Err(error) => {
                tracing::warn!(
                    %error,
                    path = %base_path,
                    "durable audit sink unavailable; event chain stays in memory only"
                );
                return 0;
            }
        };

        let timing_dir = std::path::Path::new(base_path).join("timing");
        let replayed = self.rebuild_chain_from_disk(&timing_dir).await;
        let _ = self.audit_sink.set(chain_store);
        replayed
    }

    /// Replay persisted audit events from the `timing_subvol` into the chain.
    ///
    /// Records are sorted by their persisted `event_id` so hash linkage is
    /// restored in the original order. Malformed or non-audit files (the
    /// timing directory also holds footprints written by other producers) are
    /// skipped with a `warn!` rather than aborting the rebuild.
    async fn rebuild_chain_from_disk(&self, timing_dir: &std::path::Path) -> usize {
        {
            let chain = self.event_chain.read().await;
            if !chain.events().is_empty() {
                tracing::warn!(
                    events = chain.events().len(),
                    "event chain already populated; skipping disk rebuild"
                );
                return 0;
            }
        }

        let mut dir = match tokio::fs::read_dir(timing_dir).await {
            Ok(dir) => dir,
            Err(error) => {
                tracing::info!(
                    %error,
                    path = %timing_dir.display(),
                    "no audit trail on disk yet; starting with an empty chain"
                );
                return 0;
            }
        };

        // (event_id, event_json) — sorted before replay so linkage is exact.
        let mut records: Vec<(u64, serde_json::Value)> = Vec::new();
        let mut skipped = 0usize;

        while let Ok(Some(entry)) = dir.next_entry().await {
            let path = entry.path();
            if path.extension().and_then(|e| e.to_str()) != Some("json") {
                continue;
            }
            let bytes = match tokio::fs::read(&path).await {
                Ok(bytes) => bytes,
                Err(error) => {
                    tracing::warn!(%error, path = %path.display(), "unreadable audit record");
                    skipped += 1;
                    continue;
                }
            };
            let value: serde_json::Value = match serde_json::from_slice(&bytes) {
                Ok(value) => value,
                Err(error) => {
                    tracing::warn!(%error, path = %path.display(), "malformed audit record");
                    skipped += 1;
                    continue;
                }
            };
            // Only records carrying an embedded ChainEvent are replayable;
            // other footprints in the timing directory are ignored.
            let Some(event) = value
                .get("data")
                .and_then(|d| d.get("metadata"))
                .and_then(|m| m.get("audit_event"))
            else {
                continue;
            };
            let Some(event_id) = event.get("event_id").and_then(|v| v.as_u64()) else {
                tracing::warn!(path = %path.display(), "audit record has no event_id");
                skipped += 1;
                continue;
            };
            records.push((event_id, value));
        }

        records.sort_by_key(|(event_id, _)| *event_id);

        let mut replayed = 0usize;
        {
            let mut chain = self.event_chain.write().await;
            for (event_id, value) in &records {
                match chain.replay_from_footprint(value) {
                    Ok(_) => replayed += 1,
                    Err(error) => {
                        tracing::warn!(%error, event_id, "audit record rejected during replay");
                        skipped += 1;
                    }
                }
            }
        }

        if replayed > 0 || skipped > 0 {
            tracing::info!(
                replayed,
                skipped,
                "event chain rebuilt from durable audit trail"
            );
        }
        replayed
    }

    /// Persist one chain event to the durable audit sink.
    ///
    /// Runs inline on the dispatch path (NFR-4: not deferred to a background
    /// task). A write failure is logged and swallowed — the event is already in
    /// the in-memory chain, and losing durability must not fail the caller's
    /// method call.
    ///
    /// OSCAL subid: `evt.service.event-chain.persist@v1`
    async fn persist_audit_event(&self, event: &ChainEvent) {
        let Some(sink) = self.audit_sink.get() else {
            return;
        };
        if let Err(error) = sink.add_footprint(event_to_footprint(event)).await {
            tracing::warn!(
                %error,
                event_id = event.event_id,
                "audit durability write failed; event retained in memory only"
            );
        }
    }

    /// Store the session bus connection used for `Updated` signal emission.
    /// Called from server.rs after SchemaRouter registers its interfaces.
    pub fn set_signal_bus(&self, conn: Connection) {
        let _ = self.signal_bus.set(conn);
    }

    /// Top-level keys of a whole-state value, for batch `Updated` payloads.
    fn state_keys_owned(value: &simd_json::OwnedValue) -> Option<Vec<String>> {
        value
            .as_object()
            .map(|obj| obj.keys().map(|k| k.to_string()).collect())
    }

    /// Top-level keys of a serde_json whole-state value.
    fn state_keys_serde(value: &serde_json::Value) -> Option<Vec<String>> {
        value.as_object().map(|obj| obj.keys().cloned().collect())
    }

    /// Emit the `Updated` signal on `org.opdbus.v1.PluginV1` for a given plugin.
    ///
    /// `key` is the mutated member when a single key changed; `keys` lists the
    /// top-level subtrees affected by a whole-state write. The payload always
    /// identifies what changed (`{"plugin","key"}` or `{"plugin","keys"}`) so
    /// subscribers can act on it without a follow-up query (REQ-1.5).
    ///
    /// Best-effort: if the signal bus is not yet available (early boot) or the
    /// interface is not registered for this plugin, the write still succeeds.
    /// The signal is for reactivity; SHM is the source of truth.
    async fn emit_updated_signal(
        &self,
        plugin_id: &str,
        key: Option<&str>,
        keys: Option<Vec<String>>,
    ) {
        let conn = match self.signal_bus.get() {
            Some(c) => c,
            None => {
                tracing::debug!(
                    plugin_id,
                    "signal_bus not yet available; skipping Updated signal"
                );
                return;
            }
        };
        let path = format!("/org/opdbus/v1/plugins/{plugin_id}");
        let iface_ref = match conn
            .object_server()
            .interface::<_, crate::schema_router::SchemaBackedInterface>(&*path)
            .await
        {
            Ok(r) => r,
            Err(_) => {
                tracing::debug!(
                    plugin_id,
                    "PluginV1 interface not registered at path; skipping signal"
                );
                return;
            }
        };
        let payload = match (key, keys) {
            (Some(k), _) => serde_json::json!({"plugin": plugin_id, "key": k}),
            (None, Some(ks)) => serde_json::json!({"plugin": plugin_id, "keys": ks}),
            (None, None) => serde_json::json!({"plugin": plugin_id}),
        }
        .to_string();
        if let Err(e) = crate::schema_router::SchemaBackedInterface::updated(
            iface_ref.signal_emitter(),
            &payload,
        )
        .await
        {
            tracing::debug!(plugin_id, error = %e, "Failed to emit Updated signal");
        }
    }

    /// Seed missing plugin projection files and seal current schemas from the
    /// canonical PluginSchema catalog. This runs once during bridge startup.
    /// Existing state projections are preserved; stale schema blobs are
    /// replaced because their hash no longer describes the running code.
    ///
    /// A missing or schema-stale plugin in the SHM blob catalog is blobified
    /// and sealed here. The blob IS the reflected plugin contract.
    pub async fn seed_missing_plugin_projections(&self) -> anyhow::Result<usize> {
        let state_store: Arc<dyn StateStore> = Arc::new(MemoryStore::new());
        let registry = op_plugins::DefaultPluginRegistry::new(state_store);
        let plugins = registry.load_all_plugins().await?;
        let mut seeded = 0usize;
        let mut sealed = 0usize;
        let mut blob_store = match op_blob::BlobStore::open_default() {
            Ok(store) => Some(store),
            Err(error) => {
                tracing::warn!(%error, "cannot open SHM blob catalog; missing plugins will not be auto-sealed");
                None
            }
        };

        for plugin in plugins {
            let plugin_id = plugin.name().to_string();

            let Some(schema) = plugin.schema() else {
                tracing::debug!(
                    plugin_id = %plugin_id,
                    "Skipping projection seed for plugin without PluginSchema"
                );
                continue;
            };

            if schema.name != plugin_id {
                tracing::warn!(
                    plugin_id = %plugin_id,
                    schema_name = %schema.name,
                    "Skipping projection seed for schema owned by a different plugin"
                );
                continue;
            }

            // Auto-generate or refresh the sealed blob when the running
            // schema hash differs from the active SHM catalog.
            if let Some(store) = blob_store.as_mut() {
                let canonical_id = op_blob::canonical_plugin_id(&plugin_id);
                let blob = op_blob::blobify_plugin_schema(&plugin_id, schema.clone());
                let schema_changed = store
                    .manifest(&canonical_id)
                    .map(|manifest| manifest.schema_hash.as_str())
                    != Some(blob.manifest.schema_hash.as_str());
                if schema_changed {
                    match store.write(&blob) {
                        Ok(_) => {
                            tracing::info!(
                                plugin_id = %canonical_id,
                                schema_hash = %blob.manifest.schema_hash,
                                "sealed current plugin schema into SHM catalog"
                            );
                            sealed += 1;
                        }
                        Err(error) => {
                            tracing::warn!(plugin_id = %canonical_id, %error, "failed to seal current plugin schema");
                        }
                    }
                }
            }

            if let Some(mut bytes) = op_core::projection_shm::read_projection_bytes(&plugin_id) {
                match simd_json::to_owned_value(&mut bytes) {
                    Ok(projected_state) => {
                        self.update_state_cache(plugin_id.clone(), projected_state)
                            .await;
                    }
                    Err(error) => {
                        tracing::warn!(
                            plugin_id = %plugin_id,
                            %error,
                            "existing plugin projection is invalid JSON; leaving it authoritative but uncached"
                        );
                    }
                }
                continue;
            }

            let seed_state = op_plugins::projection_seed_state_from_schema(&schema);
            let json = simd_json::to_string(&seed_state)?;
            op_core::projection_shm::write_projection(&plugin_id, json.as_bytes())?;
            self.emit_updated_signal(&plugin_id, None, Self::state_keys_owned(&seed_state))
                .await;
            self.update_state_cache(plugin_id.clone(), seed_state).await;
            seeded += 1;
        }

        tracing::info!(
            projections = seeded,
            blobs = sealed,
            "Seeded missing plugin projections and sealed current plugin schemas"
        );
        Ok(seeded)
    }

    /// Authoritative D-Bus connection getter
    pub async fn dbus_connection(&self) -> anyhow::Result<Connection> {
        self.dbus_connection
            .get_or_try_init(|| async { Connection::system().await })
            .await
            .cloned()
            .map_err(|e| anyhow::anyhow!(e))
    }

    /// Get or create the session bus connection (for projection tree introspection)
    async fn session_bus(&self) -> anyhow::Result<Connection> {
        self.session_bus
            .get_or_try_init(|| async {
                let addr = std::env::var("DBUS_SESSION_BUS_ADDRESS")
                    .unwrap_or_else(|_| op_core::config::SESSION_BUS_ADDRESS.to_string());
                zbus::connection::Builder::address(addr.as_str())
                    .map_err(|e| anyhow::anyhow!("Builder::address: {}", e))?
                    .build()
                    .await
                    .map_err(|e| anyhow::anyhow!("Session bus connect: {}", e))
            })
            .await
            .cloned()
            .map_err(|e| anyhow::anyhow!(e))
    }

    /// Crawl the D-Bus projection tree for a plugin and return its full state
    /// as JSON. Introspects `/org/opdbus/v1/plugins/<plugin_id>`, recursively
    /// descends child nodes, and reads all properties from all interfaces.
    async fn crawl_plugin_dbus_tree(&self, plugin_id: &str) -> Option<simd_json::OwnedValue> {
        let conn = match self.session_bus().await {
            Ok(c) => c,
            Err(e) => {
                tracing::debug!(error = %e, "session bus unavailable for crawl");
                return None;
            }
        };

        let root_path = format!("/org/opdbus/v1/plugins/{}", plugin_id);
        let bus_name = "org.opdbus.v1.plugins";

        let mut result = simd_json::value::owned::Object::new();
        Self::crawl_path(&conn, bus_name, &root_path, &mut result).await;
        if result.is_empty() {
            None
        } else {
            Some(simd_json::OwnedValue::Object(Box::new(result)))
        }
    }

    /// Recursively introspect a D-Bus path, reading properties and descending
    /// into child nodes.
    async fn crawl_path(
        conn: &Connection,
        bus_name: &str,
        path: &str,
        out: &mut simd_json::value::owned::Object,
    ) {
        // Introspect to discover interfaces and child nodes
        let introspect_xml: String = match conn
            .call_method(
                Some(bus_name),
                path,
                Some("org.freedesktop.DBus.Introspectable"),
                "Introspect",
                &(),
            )
            .await
        {
            Ok(msg) => msg.body().deserialize::<String>().unwrap_or_default(),
            Err(e) => {
                tracing::debug!(path = %path, error = %e, "introspect failed");
                return;
            }
        };

        // Parse the introspection XML for interfaces and child nodes
        let interfaces = Self::parse_interfaces(&introspect_xml);
        let child_nodes = Self::parse_child_nodes(&introspect_xml);

        // Read properties from each non-standard interface
        for iface in &interfaces {
            // Skip standard D-Bus interfaces
            if iface.starts_with("org.freedesktop.DBus.") {
                continue;
            }

            let props: std::collections::HashMap<String, zbus::zvariant::OwnedValue> = match conn
                .call_method(
                    Some(bus_name),
                    path,
                    Some("org.freedesktop.DBus.Properties"),
                    "GetAll",
                    &iface,
                )
                .await
            {
                Ok(msg) => msg
                    .body()
                    .deserialize::<std::collections::HashMap<String, zbus::zvariant::OwnedValue>>()
                    .unwrap_or_default(),
                Err(_) => std::collections::HashMap::new(),
            };

            let mut iface_obj = simd_json::value::owned::Object::new();
            for (prop_name, prop_val) in &props {
                // zvariant::OwnedValue serializes as {"signature":"s","value":"..."}
                // Extract just the value field for a clean JSON projection.
                let json_val: serde_json::Value =
                    serde_json::to_value(prop_val).unwrap_or(serde_json::Value::Null);
                let extracted = json_val.get("value").unwrap_or(&json_val);
                let json_str =
                    serde_json::to_string(extracted).unwrap_or_else(|_| "null".to_string());
                let mut bytes = json_str.into_bytes();
                if let Ok(v) = simd_json::to_owned_value(&mut bytes) {
                    iface_obj.insert(prop_name.clone(), v);
                }
            }
            if !iface_obj.is_empty() {
                out.insert(
                    iface.clone(),
                    simd_json::OwnedValue::Object(Box::new(iface_obj)),
                );
            }
        }

        // Recurse into child nodes
        for child in &child_nodes {
            let child_path = format!("{}/{}", path.trim_end_matches('/'), child);
            let mut child_obj = simd_json::value::owned::Object::new();
            Box::pin(Self::crawl_path(
                conn,
                bus_name,
                &child_path,
                &mut child_obj,
            ))
            .await;
            if !child_obj.is_empty() {
                out.insert(
                    child.clone(),
                    simd_json::OwnedValue::Object(Box::new(child_obj)),
                );
            }
        }
    }

    /// Parse interface names from D-Bus introspection XML
    fn parse_interfaces(xml: &str) -> Vec<String> {
        let mut interfaces = Vec::new();
        for line in xml.lines() {
            let trimmed = line.trim();
            if let Some(rest) = trimmed.strip_prefix("<interface name=\"") {
                if let Some(end) = rest.find("\">") {
                    interfaces.push(rest[..end].to_string());
                }
            }
        }
        interfaces
    }

    /// Parse child node names from D-Bus introspection XML
    fn parse_child_nodes(xml: &str) -> Vec<String> {
        let mut nodes = Vec::new();
        for line in xml.lines() {
            let trimmed = line.trim();
            if let Some(rest) = trimmed.strip_prefix("<node name=\"") {
                if let Some(end) = rest.find("\"") {
                    nodes.push(rest[..end].to_string());
                }
            }
        }
        nodes
    }

    fn compute_tags(&self, plugin_id: &str, object_path: &str) -> Vec<String> {
        let mut tags = Vec::new();
        if plugin_id == "net" || object_path.contains("/ovsdb/") {
            tags.push("network".to_string());
            tags.push("ovsdb".to_string());
        } else {
            tags.push("state".to_string());
            tags.push(plugin_id.to_string());
        }
        tags
    }

    /// Process a change that has already happened in an authoritative store.
    /// This records the change in the event chain and broadcasts it to gRPC.
    #[allow(clippy::too_many_arguments)]
    pub async fn process_authoritative_change(
        &self,
        plugin_id: String,
        object_path: String,
        change_type: ChangeType,
        member_name: Option<String>,
        old_value: Option<simd_json::OwnedValue>,
        new_value: simd_json::OwnedValue,
        mut tags: Vec<String>,
        actor_id: String,
        capability_id: Option<String>,
        source: ChangeSource,
    ) -> Result<StateChange, String> {
        if tags.is_empty() {
            tags = self.compute_tags(&plugin_id, &object_path);
        }

        let event = {
            let mut chain = self.event_chain.write().await;
            let op = match change_type {
                ChangeType::PropertySet => OperationType::PropertySet,
                ChangeType::ObjectRemoved => OperationType::Custom("delete".to_string()),
                _ => OperationType::EmitSignal,
            };
            if let Some(capability) = capability_id {
                let event = ChainEvent::new(
                    chain.next_event_id(),
                    chain.last_hash().to_string(),
                    actor_id.clone(),
                    plugin_id.clone(),
                    "1.0.0".to_string(),
                    op,
                    object_path.clone(),
                    tags.clone(),
                    Decision::Allow,
                    &new_value,
                )
                .with_capability(capability);
                chain.append(event).clone()
            } else {
                let event = chain.record(
                    actor_id.clone(),
                    plugin_id.clone(),
                    "1.0.0".to_string(),
                    op,
                    object_path.clone(),
                    tags.clone(),
                    Decision::Allow,
                    &new_value,
                );
                event.clone()
            }
        };

        // Durability: mirror the event into the timing_subvol so it survives a
        // restart. Inline with the change, never deferred.
        self.persist_audit_event(&event).await;

        self.update_cached_plugin_state(
            &plugin_id,
            &object_path,
            change_type,
            member_name.as_deref(),
            &new_value,
        )
        .await;

        // Write the plugin's present state verbatim to the shm static tree.
        //
        // The projection IS the state — `/dev/shm/opdbus/state/<plugin>.json`
        // is the single source of truth that the D-Bus tree (schema_router)
        // and op-web's state_tree read from. The `{"data","_introspection"}`
        // composite existed only for the deleted projection server's child-path
        // derivation; readers expect the raw state object.
        if change_type != ChangeType::ObjectRemoved {
            match simd_json::to_string(&new_value) {
                Ok(json) => {
                    if let Err(e) =
                        op_core::projection_shm::write_projection(&plugin_id, json.as_bytes())
                    {
                        tracing::warn!(plugin_id = %plugin_id, error = %e, "Failed to write shm projection");
                    } else {
                        let keys = if member_name.is_some() {
                            None
                        } else {
                            Self::state_keys_owned(&new_value)
                        };
                        self.emit_updated_signal(&plugin_id, member_name.as_deref(), keys)
                            .await;
                    }
                }
                Err(e) => {
                    tracing::warn!(
                        plugin_id = %plugin_id,
                        error = %e,
                        "Failed to serialize plugin state for shm projection"
                    );
                }
            }
        }

        let change = StateChange {
            change_id: uuid::Uuid::new_v4().to_string(),
            event_id: event.event_id,
            plugin_id,
            object_path,
            change_type,
            member_name,
            old_value,
            new_value,
            tags_touched: tags,
            event_hash: event.event_hash.clone(),
            timestamp: event.timestamp,
            actor_id,
            source,
        };

        let _ = self.change_tx.send(change.clone());
        Ok(change)
    }

    /// Start the Mutation Engine background tasks.
    /// Subscribes to authoritative RCP stores and broadcasts changes.
    pub async fn start(self: Arc<Self>) -> anyhow::Result<()> {
        let me = self.clone();

        // Subscribe to OVSDB updates
        let ovsdb_self = me.clone();
        tokio::spawn(async move {
            if let Ok(mut rx) = ovsdb_self.ovsdb.monitor_db("Open_vSwitch").await {
                loop {
                    match rx.recv().await {
                        Ok(update) => {
                            if let Some(params) = update.get("params").and_then(|p| p.as_array()) {
                                if params.len() >= 3 {
                                    if let Some(tables) = params[2].as_object() {
                                        for (table_name, table_update) in tables.iter() {
                                            let table_name_owned: String = table_name.to_string();
                                            // monitor_db returns serde_json::Value; convert to
                                            // simd_json::OwnedValue required by process_authoritative_change.
                                            let simd_val: simd_json::OwnedValue = {
                                                match serde_json::to_string(table_update)
                                                    .ok()
                                                    .and_then(|s| {
                                                        let mut b = s.into_bytes();
                                                        simd_json::to_owned_value(&mut b).ok()
                                                    }) {
                                                    Some(v) => v,
                                                    None => continue,
                                                }
                                            };
                                            let _ = ovsdb_self
                                                .process_authoritative_change(
                                                    "net".to_string(),
                                                    format!(
                                                        "/org/opdbus/v1/ovsdb/{}",
                                                        table_name_owned
                                                    ),
                                                    ChangeType::PropertySet,
                                                    Some(table_name_owned),
                                                    None,
                                                    simd_val,
                                                    vec![
                                                        "ovsdb".to_string(),
                                                        "network".to_string(),
                                                    ],
                                                    "ovsdb-monitor".to_string(),
                                                    None,
                                                    ChangeSource::DBus,
                                                )
                                                .await;
                                        }
                                    }
                                }
                            }
                        }
                        Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                            tracing::warn!("OVSDB subscription lagged by {} events", n);
                            continue;
                        }
                        Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
                    }
                }
            }
        });

        Ok(())
    }

    /// Unified mutation entry point. Writes to authoritative RCP stores and
    /// triggers the event recording/broadcast pipeline.
    #[allow(clippy::too_many_arguments)]
    pub async fn mutate(
        &self,
        plugin_id: String,
        object_path: String,
        change_type: ChangeType,
        member_name: Option<String>,
        value: simd_json::OwnedValue,
        actor_id: String,
        capability_id: Option<String>,
    ) -> anyhow::Result<MutationResult> {
        let mut old_value = None;
        let mut authoritative_value = value.clone();
        let mut caller_result = None;

        // Resolve the acting identity from the Sled (/dev/shm/plugin_schema.dat)
        // when the caller omitted it. The Sled carries the WireGuard footprint +
        // trace_id — that identity is authoritative for every mutation.
        let actor_id = if actor_id.is_empty() {
            sled_footprint().unwrap_or_else(|| "anonymous".to_string())
        } else {
            actor_id
        };

        // 1. Write to authoritative RCP store
        if plugin_id == "net" || object_path.contains("/ovsdb/") {
            // OVSDB Authoritative Path
            if change_type == ChangeType::MethodCall {
                if let Some(method) = &member_name {
                    match method.as_str() {
                        "create_bridge" => {
                            if let Some(name) = value.as_str() {
                                self.ovsdb.create_bridge(name).await?;
                            }
                        }
                        "add_port" => {
                            if let Some(args) = value.as_array() {
                                if args.len() >= 2 {
                                    if let (Some(br), Some(port)) =
                                        (args[0].as_str(), args[1].as_str())
                                    {
                                        self.ovsdb.add_port(br, port).await?;
                                    }
                                }
                            }
                        }
                        _ => {
                            // Fallback to generic D-Bus call if it's a known service
                            let _ = self
                                .call_dbus_method(
                                    &format!("org.opdbus.{}.v1", plugin_id),
                                    &object_path,
                                    "org.opdbus.OvsdbV1",
                                    method,
                                    vec![value.clone()],
                                    &actor_id,
                                    &capability_id,
                                )
                                .await?;
                        }
                    }
                }
            } else if change_type == ChangeType::PropertySet {
                if let Some(prop) = &member_name {
                    // Extract bridge name from path if possible
                    // Path format: /org/opdbus/v1/ovsdb/Bridge/bridge_name
                    let parts: Vec<&str> = object_path.split('/').collect();
                    if parts.len() >= 6 && parts[4] == "Bridge" {
                        let br_name = parts[5].replace('_', "-");
                        if let Some(val_str) = value.as_str() {
                            self.ovsdb
                                .set_bridge_property(&br_name, prop, val_str)
                                .await?;
                        }
                    }
                }
            }
        } else if plugin_id == "unix_socket" && change_type == ChangeType::MethodCall {
            // unix_socket plugin dispatch: createunixsocket <name> <ports csv/vec>.
            // The method registers the name+ports routing tag against the
            // shared container.sock transport; the transport owner is not
            // replaced during registration.
            if let Some(method) = &member_name {
                if method == "createunixsocket" {
                    let (name, ports) = parse_socket_args(&value);
                    let result = self
                        .unix_socket
                        .create_unix_socket(name.clone(), ports.clone());
                    if !result.success {
                        anyhow::bail!(result.errors.join("; "));
                    }
                    authoritative_value = unix_socket_state_after_registration(&name, &ports);
                }
            }
        } else if plugin_id == "identity_sled" && change_type == ChangeType::MethodCall {
            // PluginService.CallMethod wraps object arguments in a one-element
            // array. The identity dispatcher owns provisioning, durable Cozo
            // persistence, and the native Btrfs attach operation.
            if let Some(method) = &member_name {
                let mut args_json = serde_json::to_value(&value)?;
                if let serde_json::Value::Array(items) = &args_json {
                    args_json = items
                        .first()
                        .cloned()
                        .unwrap_or_else(|| serde_json::Value::Object(Default::default()));
                }
                let domain = crate::identity_sled_dispatch::dispatch_identity_sled_method(
                    self, method, &args_json,
                )
                .await?;
                if let Some(state) = self.get_state("identity_sled").await {
                    authoritative_value = state;
                }
                caller_result = Some(simd_json::serde::to_owned_value(&domain)?);
            }
        } else if plugin_id == "xray" && change_type == ChangeType::MethodCall {
            // PluginService.CallMethod wraps object arguments in a
            // one-element array, matching identity_sled's convention above.
            if let Some(method) = &member_name {
                let mut args_json = serde_json::to_value(&value)?;
                if let serde_json::Value::Array(items) = &args_json {
                    args_json = items
                        .first()
                        .cloned()
                        .unwrap_or_else(|| serde_json::Value::Object(Default::default()));
                }
                let result = dispatch_xray_method(method, &args_json).await?;
                caller_result = Some(simd_json::serde::to_owned_value(&result)?);
            }
        } else if plugin_id == "netmaker" && change_type == ChangeType::MethodCall {
            if let Some(method) = &member_name {
                let mut args_json = serde_json::to_value(&value)?;
                if let serde_json::Value::Array(items) = &args_json {
                    args_json = items
                        .first()
                        .cloned()
                        .unwrap_or_else(|| serde_json::Value::Object(Default::default()));
                }
                let result = op_plugins::state_plugins::netmaker::dispatch_netmaker_method(
                    method, &args_json,
                )
                .await?;
                caller_result = Some(simd_json::serde::to_owned_value(&result)?);
            }
        } else {
            // NonNet / Generic Plugin Path
            if change_type == ChangeType::PropertySet {
                // Get old value for the footprint before update from cache
                old_value = self.get_state(&plugin_id).await.and_then(|v| {
                    if let Some(prop) = &member_name {
                        v.get(prop).cloned()
                    } else {
                        Some(v)
                    }
                });
            }
        }

        // 2. Record and broadcast change
        let change = self
            .process_authoritative_change(
                plugin_id,
                object_path,
                change_type,
                member_name,
                old_value,
                authoritative_value.clone(),
                vec![], // Automatically computed in process_authoritative_change
                actor_id,
                capability_id,
                ChangeSource::Grpc,
            )
            .await
            .map_err(|e| anyhow::anyhow!(e))?;

        // Write the Identity Sled with the updated mutation index.
        {
            let (existing_pubkey_b64, existing_trace_hex) = if let Ok((ptr, _mmap)) = read_sled() {
                unsafe {
                    let sled = &*ptr;
                    (
                        base64::engine::general_purpose::STANDARD.encode(sled.wireguard_pubkey),
                        sled.trace_id_hex(),
                    )
                }
            } else {
                (String::new(), String::new())
            };
            if let Err(e) =
                write_sled_full(&existing_pubkey_b64, change.event_id, &existing_trace_hex)
            {
                tracing::warn!("sled write after mutation failed: {}", e);
            }
        }

        Ok(MutationResult {
            success: true,
            event_id: change.event_id,
            event_hash: change.event_hash,
            result: caller_result.or(Some(authoritative_value)),
            error: None,
        })
    }

    /// Backward-compatible wrapper for gRPC Mutations.
    #[allow(clippy::too_many_arguments)]
    pub async fn process_grpc_mutation(
        &self,
        plugin_id: String,
        object_path: String,
        change_type: ChangeType,
        member_name: Option<String>,
        value: simd_json::OwnedValue,
        actor_id: String,
        capability_id: Option<String>,
    ) -> anyhow::Result<MutationResult> {
        self.mutate(
            plugin_id,
            object_path,
            change_type,
            member_name,
            value,
            actor_id,
            capability_id,
        )
        .await
    }

    /// Dispatch a method call from the schema-backed bridge interface.
    ///
    /// This is the real dispatch path for `SchemaBackedInterface::call`
    /// (Requirement 5). After method validation and capability enforcement
    /// at the bridge layer, the bridge calls this method with the verbatim
    /// `json_args` string from the caller.
    ///
    /// The method:
    /// 1. Records an immutable event in the event chain via
    ///    [`EventChain::record_method_call`] including `actor_id`,
    ///    `plugin_id`, `method_name`, `capability_id`, and a Blake3
    ///    footprint of `json_args` (Requirement 5.5 / VAL-DISPATCH-005).
    /// 2. The append occurs **before** the call returns success
    ///    (NFR-003 / VAL-NFR-003).
    /// 3. Broadcasts the change to subscribers.
    /// 4. Returns the result as a `serde_json::Value`.
    ///
    /// Errors are propagated to the caller as `zbus::fdo::Error::Failed`
    /// (D-Bus) or gRPC `Status::internal` (Requirement 5.3 /
    /// VAL-DISPATCH-003) by the calling bridge interface.
    pub async fn dispatch_method_call(
        &self,
        plugin_id: &str,
        method: &str,
        json_args: &str,
        capability_id: Option<&str>,
        actor_id: &str,
    ) -> anyhow::Result<serde_json::Value> {
        // Test-only: ForceDispatchError triggers an error for VAL-DISPATCH-003 testing.
        // This allows tests to verify error propagation without using malformed JSON
        // (which would now be rejected by the arg-validation gate at the bridge layer).
        if method == "ForceDispatchError" {
            return Err(anyhow::anyhow!(
                "dispatch error: method explicitly triggered failure"
            ));
        }

        // Parse the verbatim json_args string. If parsing fails, propagate
        // the error — the bridge converts it to fdo::Error::Failed.
        let parsed_value: simd_json::OwnedValue = {
            let mut bytes = json_args.as_bytes().to_vec();
            simd_json::to_owned_value(&mut bytes)
                .map_err(|e| anyhow::anyhow!("invalid json_args for method '{}': {}", method, e))?
        };

        // Record the immutable event with the full accountability surface.
        // The append happens under the event chain write lock, guaranteeing
        // it is persisted before this method returns Ok (NFR-003).
        let event_summary = {
            let mut chain = self.event_chain.write().await;
            let event = chain.record_method_call(
                actor_id.to_string(),
                plugin_id.to_string(),
                method.to_string(),
                capability_id.map(|s| s.to_string()),
                json_args, // verbatim string for Blake3 footprint
            );
            (
                event.event_id,
                event.event_hash.clone(),
                event.timestamp,
                event.clone(),
            )
        };

        // Durability: write the event to the timing_subvol before returning, so
        // the audit trail survives a restart (FR-6). A failure here is logged
        // and does not fail the dispatch (NFR-4).
        self.persist_audit_event(&event_summary.3).await;

        // Broadcast the method-call change to gRPC subscribers.
        let change = StateChange {
            change_id: uuid::Uuid::new_v4().to_string(),
            event_id: event_summary.0,
            plugin_id: plugin_id.to_string(),
            object_path: format!("/org/opdbus/v1/plugins/{}", plugin_id),
            change_type: ChangeType::MethodCall,
            member_name: Some(method.to_string()),
            old_value: None,
            new_value: parsed_value.clone(),
            tags_touched: vec![],
            event_hash: event_summary.1.clone(),
            timestamp: event_summary.2,
            actor_id: actor_id.to_string(),
            source: ChangeSource::DBus,
        };
        let _ = self.change_tx.send(change.clone());

        // Dispatch to appropriate backend based on plugin_id
        let method_result: serde_json::Value = match plugin_id {
            "rtnetlink" => dispatch_rtnetlink_method(method, &parsed_value).await?,
            "rovs_commands" => {
                dispatch_rovs_commands_method(&self.ovsdb, method, &parsed_value).await?
            }
            "ovsdb_bridge" => {
                dispatch_ovsdb_bridge_method(&self.ovsdb, method, &parsed_value).await?
            }
            "xray" => {
                let args = serde_json::to_value(&parsed_value)?;
                dispatch_xray_method(method, &args).await?
            }
            "identity_sled" => {
                let args = serde_json::to_value(&parsed_value)?;
                crate::identity_sled_dispatch::dispatch_identity_sled_method(self, method, &args)
                    .await?
            }
            "persona" => {
                let args = serde_json::to_value(&parsed_value)?;
                op_plugins::state_plugins::persona::dispatch_persona_method(method, &args).await?
            }
            "gcloud_adc" => {
                let args = serde_json::to_value(&parsed_value)?;
                op_plugins::state_plugins::gcloud_adc::dispatch_gcloud_adc_method(method, &args)
                    .await?
            }
            "compact_mcp" => {
                let args = serde_json::to_value(&parsed_value)?;
                op_plugins::state_plugins::compact_mcp::dispatch_compact_mcp_method(method, &args)
                    .await?
            }
            "full_system" => {
                let args = serde_json::to_value(&parsed_value)?;
                op_plugins::state_plugins::full_system::dispatch_full_system_method(method, &args)
                    .await?
            }
            "keyring" => {
                let args = serde_json::to_value(&parsed_value)?;
                op_plugins::state_plugins::keyring::dispatch_keyring_method(method, &args).await?
            }
            "privacy_routes" => {
                let args = serde_json::to_value(&parsed_value)?;
                op_plugins::state_plugins::privacy_routes::dispatch_privacy_routes_method(
                    method, &args,
                )
                .await?
            }
            "zeroclaw" => {
                let state = self
                    .projected_state::<op_plugins::state_plugins::zeroclaw::ZeroclawState>(
                        "zeroclaw",
                    )
                    .await
                    .unwrap_or_else(
                        op_plugins::state_plugins::zeroclaw::ZeroclawPlugin::current_state,
                    );
                if method == "Chat" {
                    let args = serde_json::from_value::<
                        op_plugins::state_plugins::zeroclaw::ChatInput,
                    >(serde_json::to_value(&parsed_value)?)
                    .context("invalid zeroclaw.Chat arguments")?;
                    serde_json::to_value(
                        crate::chat_service::dispatch_schema_chat(
                            self.chat_manager.as_ref(),
                            &state,
                            args,
                        )
                        .await?,
                    )?
                } else {
                    match op_plugins::state_plugins::zeroclaw::dispatch_zeroclaw_method(
                        method, json_args, &state,
                    ) {
                        Ok(outcome) => {
                            if method.starts_with("Set") {
                                self.persist_zeroclaw_mutation(method, &outcome.result)
                                    .await?;
                            }
                            if let Some(sig) = &outcome.signal {
                                self.broadcast_method_signal(&change, &sig.name, &sig.payload);
                            }
                            outcome.result
                        }
                        Err(e) => {
                            return Err(anyhow::anyhow!(
                                "zeroclaw dispatch error for '{}': {}",
                                method,
                                e
                            ))
                        }
                    }
                }
            }
            "ghostbridge" => {
                let state = self
                    .projected_state::<op_plugins::state_plugins::ghostbridge::GhostbridgeState>(
                        "ghostbridge",
                    )
                    .await
                    .unwrap_or_else(
                        op_plugins::state_plugins::ghostbridge::GhostbridgePlugin::current_state,
                    );
                op_plugins::state_plugins::ghostbridge::dispatch_ghostbridge_method(method, &state)?
            }
            "cognitive_mcp" => {
                let args = serde_json::to_value(&parsed_value)?;
                dispatch_cognitive_mcp_method(method, &args).await?
            }
            // Audit-trail query surface. Deliberately scoped: only the two
            // audit methods are wired. The plugin's seven pre-existing methods
            // (snapshots, retention, rollback) fall through to the echo below,
            // exactly as before, until the schema-methods sweep wires them.
            "blockchain" => match method {
                "query_events" => {
                    dispatch_blockchain_query_events(&self.event_chain, &parsed_value).await?
                }
                "verify_chain" => {
                    dispatch_blockchain_verify_chain(&self.event_chain, &parsed_value).await?
                }
                _ => serde_json::to_value(&parsed_value).unwrap_or(serde_json::Value::Null),
            },
            _ => serde_json::to_value(&parsed_value).unwrap_or(serde_json::Value::Null),
        };

        // Return a JSON result carrying the event accountability proof and the
        // method's domain result. This is the value the bridge serializes and
        // returns to the D-Bus/gRPC caller.
        let result = serde_json::json!({
            "success": true,
            "event_id": change.event_id,
            "event_hash": change.event_hash,
            "plugin_id": plugin_id,
            "method": method,
            "result": method_result,
        });
        Ok(result)
    }

    async fn projected_state<T>(&self, plugin_id: &str) -> Option<T>
    where
        T: serde::de::DeserializeOwned,
    {
        if let Some(value) = self.get_state(plugin_id).await {
            if let Ok(json) = serde_json::to_value(value) {
                if let Ok(state) = serde_json::from_value(json) {
                    return Some(state);
                }
            }
        }

        let mut bytes = op_core::projection_shm::read_projection_bytes(plugin_id)?;
        let value = simd_json::to_owned_value(&mut bytes).ok()?;
        let json = serde_json::to_value(&value).ok()?;
        let state = serde_json::from_value(json).ok()?;
        self.update_state_cache(plugin_id.to_string(), value).await;
        Some(state)
    }

    fn broadcast_method_signal(
        &self,
        method_change: &StateChange,
        signal_name: &str,
        payload: &serde_json::Value,
    ) {
        let mut bytes = serde_json::to_vec(payload).unwrap_or_default();
        let payload =
            simd_json::to_owned_value(&mut bytes).unwrap_or_else(|_| simd_json::json!(null));
        let signal = StateChange {
            change_id: uuid::Uuid::new_v4().to_string(),
            event_id: method_change.event_id,
            plugin_id: method_change.plugin_id.clone(),
            object_path: method_change.object_path.clone(),
            change_type: ChangeType::Signal,
            member_name: Some(signal_name.to_string()),
            old_value: None,
            new_value: payload,
            tags_touched: method_change.tags_touched.clone(),
            event_hash: method_change.event_hash.clone(),
            timestamp: method_change.timestamp,
            actor_id: method_change.actor_id.clone(),
            source: method_change.source,
        };
        let _ = self.change_tx.send(signal);
    }

    async fn persist_zeroclaw_mutation(
        &self,
        method: &str,
        result: &serde_json::Value,
    ) -> anyhow::Result<()> {
        match method {
            "SetProvider" | "SetModel" => {
                self.merge_into_state_cache("zeroclaw", result).await;
            }
            "SetOvsRoutingModel"
            | "SetObfuscationModel"
            | "SetVectorizationModel"
            | "SetQdrantRetrievalModel"
            | "SetCozoRetrievalModel" => {
                self.merge_nested_into_state_cache("zeroclaw", "model_assignments", result)
                    .await;
            }
            _ => {}
        }

        self.publish_plugin_projection_from_cache("zeroclaw", ChangeType::PropertySet)
            .await
    }

    /// Merge a flat JSON object of changed fields into the authoritative
    /// in-memory state cache for `plugin_id` (used to persist Zeroclaw `Set*`
    /// selection changes so readers observe the new effective state).
    async fn merge_into_state_cache(&self, plugin_id: &str, changes: &serde_json::Value) {
        let changes_obj = match changes.as_object() {
            Some(o) => o,
            None => return,
        };
        let mut current = self
            .get_state(plugin_id)
            .await
            .and_then(|v| serde_json::to_value(&v).ok())
            .unwrap_or_else(|| serde_json::json!({}));
        if let Some(cur_obj) = current.as_object_mut() {
            for (k, v) in changes_obj {
                cur_obj.insert(k.clone(), v.clone());
            }
        }
        let mut bytes = serde_json::to_vec(&current).unwrap_or_default();
        if let Ok(owned) = simd_json::to_owned_value(&mut bytes) {
            self.update_state_cache(plugin_id.to_string(), owned).await;
        }
    }

    async fn merge_nested_into_state_cache(
        &self,
        plugin_id: &str,
        field: &str,
        changes: &serde_json::Value,
    ) {
        let Some(changes_obj) = changes.as_object() else {
            return;
        };
        let mut current = self
            .get_state(plugin_id)
            .await
            .and_then(|value| serde_json::to_value(value).ok())
            .unwrap_or_else(|| serde_json::json!({}));

        let Some(current_obj) = current.as_object_mut() else {
            return;
        };
        let nested = current_obj
            .entry(field.to_string())
            .or_insert_with(|| serde_json::json!({}));
        let Some(nested_obj) = nested.as_object_mut() else {
            return;
        };
        for (key, value) in changes_obj {
            nested_obj.insert(key.clone(), value.clone());
        }

        let mut bytes = serde_json::to_vec(&current).unwrap_or_default();
        if let Ok(owned) = simd_json::to_owned_value(&mut bytes) {
            self.update_state_cache(plugin_id.to_string(), owned).await;
        }
    }

    /// Fetch current state for a specific plugin from authoritative cache
    pub async fn get_state(&self, plugin_id: &str) -> Option<simd_json::OwnedValue> {
        let cache = self.state_cache.read().await;
        cache.get(plugin_id).cloned()
    }

    /// Update the authoritative state cache
    pub async fn update_state_cache(&self, plugin_id: String, state: simd_json::OwnedValue) {
        let mut cache = self.state_cache.write().await;
        cache.insert(plugin_id, state);
    }

    /// Publish the current authoritative cache entry into the plugin's SHM
    /// projection after a domain dispatcher has completed its mutation.
    pub async fn publish_plugin_projection_from_cache(
        &self,
        plugin_id: &str,
        change_type: ChangeType,
    ) -> anyhow::Result<()> {
        let Some(state) = self.get_state(plugin_id).await else {
            return Ok(());
        };
        let new_value = serde_json::to_value(&state)?;
        let crawl = match tokio::time::timeout(
            std::time::Duration::from_secs(3),
            self.crawl_plugin_dbus_tree(plugin_id),
        )
        .await
        {
            Ok(value) => value,
            Err(_) => {
                tracing::warn!(
                    plugin_id,
                    "plugin D-Bus crawl timed out; projecting cached state"
                );
                None
            }
        };
        // The shm state file holds present state verbatim; the composite is
        // only carried on the broadcast `StateChange` for event-stream consumers.
        let state_owned = simd_json::serde::to_owned_value(&new_value)?;
        let json = simd_json::to_string(&state_owned)?;
        op_core::projection_shm::write_projection(plugin_id, json.as_bytes())?;
        self.emit_updated_signal(plugin_id, None, Self::state_keys_serde(&new_value))
            .await;
        let projection = if let Some(crawl) = crawl {
            simd_json::json!({ "data": new_value, "_introspection": crawl })
        } else {
            state_owned
        };
        let change = StateChange {
            change_id: uuid::Uuid::new_v4().to_string(),
            event_id: 0,
            plugin_id: plugin_id.to_string(),
            object_path: format!("/org/opdbus/v1/plugins/{plugin_id}"),
            change_type,
            member_name: None,
            old_value: None,
            new_value: projection,
            tags_touched: vec![],
            event_hash: String::new(),
            timestamp: chrono::Utc::now(),
            actor_id: "identity_sled_dispatch".to_string(),
            source: ChangeSource::Internal,
        };
        let _ = self.change_tx.send(change);
        Ok(())
    }

    async fn update_cached_plugin_state(
        &self,
        plugin_id: &str,
        object_path: &str,
        change_type: ChangeType,
        property: Option<&str>,
        new_value: &simd_json::OwnedValue,
    ) {
        if object_path.starts_with("schema/") {
            return;
        }

        let mut cache = self.state_cache.write().await;

        match change_type {
            ChangeType::ObjectRemoved => {
                cache.remove(plugin_id);
            }
            ChangeType::PropertySet => {
                if let Some(property) = property {
                    let entry = cache
                        .entry(plugin_id.to_string())
                        .or_insert_with(|| simd_json::json!({}));

                    if let Some(existing) = entry.as_object_mut() {
                        existing.insert(property.to_string(), new_value.clone());
                    } else {
                        let mut state = simd_json::value::owned::Object::new();
                        state.insert(property.to_string(), new_value.clone());
                        *entry = simd_json::OwnedValue::Object(Box::new(state));
                    }
                } else {
                    cache.insert(plugin_id.to_string(), new_value.clone());
                }
            }
            _ => {}
        }
    }

    /// Route a D-Bus method call through the authoritative bridge
    #[allow(clippy::too_many_arguments)]
    pub async fn call_dbus_method(
        &self,
        bus_name: &str,
        path: &str,
        interface: &str,
        method: &str,
        _args: Vec<simd_json::OwnedValue>,
        _actor_id: &str,
        capability_id: &Option<String>,
    ) -> anyhow::Result<simd_json::OwnedValue> {
        tracing::debug!(
            bus_name,
            path,
            interface,
            method,
            capability_id = ?capability_id,
            "Routing D-Bus method call through authoritative bridge"
        );
        let conn = self.dbus_connection().await?;
        let proxy = Proxy::new(&conn, bus_name, path, interface).await?;
        let result: ZOwnedValue = proxy.call(method, &()).await?;
        simd_json::serde::to_owned_value(&result).map_err(|e| anyhow::anyhow!(e))
    }

    pub fn change_tx(&self) -> broadcast::Sender<StateChange> {
        self.change_tx.clone()
    }
}

/// Result of an authoritative mutation
#[derive(Debug, Clone)]
pub struct MutationResult {
    pub success: bool,
    pub event_id: u64,
    pub event_hash: String,
    pub result: Option<simd_json::OwnedValue>,
    pub error: Option<MutationError>,
}

#[derive(Debug, Clone)]
pub struct MutationError {
    pub code: ErrorCode,
    pub message: String,
}

#[derive(Debug, Clone, Copy)]
pub enum ErrorCode {
    NotFound,
    PermissionDenied,
    ValidationFailed,
    ReadOnly,
    Internal,
}

/// Read the WireGuard footprint from the Sled (1:1 shared memory identity at
/// `/dev/shm/plugin_schema.dat`). Returns the hex footprint used as the default
/// `actor_id` when a caller omits identity.
fn sled_footprint() -> Option<String> {
    // SAFETY: read_sled returns a valid pointer to IdentitySled in shared memory
    // for the lifetime of the process; we copy the footprint out and drop the ptr.
    let (ptr, _mmap) = read_sled().ok()?;
    unsafe {
        let sled = &*ptr;
        if sled.hashed_footprint != [0u8; 32] {
            Some(hex::encode(sled.hashed_footprint))
        } else {
            None
        }
    }
}

/// Build the authoritative `unix_socket` projection state after a successful
/// `createunixsocket` mutation. The mutation argument is not state; the state is
/// the registered service list under the single shared container socket.
fn unix_socket_state_after_registration(name: &str, ports: &[u16]) -> simd_json::OwnedValue {
    let mut sockets = existing_unix_socket_sockets();
    sockets.retain(|socket| {
        socket
            .get("name")
            .and_then(|value| value.as_str())
            .map(|existing_name| existing_name != name)
            .unwrap_or(true)
    });

    sockets.push(simd_json::json!({
        "name": name,
        "path": op_plugins::state_plugins::unix_socket::SHARED_CONTAINER_SOCKET,
        "ports": ports,
        "protocol": "grpc",
        "label": "",
    }));

    simd_json::json!({ "sockets": sockets })
}

fn existing_unix_socket_sockets() -> Vec<simd_json::OwnedValue> {
    let Some(mut bytes) = op_core::projection_shm::read_projection_bytes("unix_socket") else {
        return Vec::new();
    };
    let Ok(state) = simd_json::to_owned_value(&mut bytes) else {
        return Vec::new();
    };

    let sockets = state
        .get("sockets")
        .and_then(|value| value.as_array())
        .or_else(|| {
            state
                .get("data")
                .and_then(|data| data.get("sockets"))
                .and_then(|value| value.as_array())
        });

    sockets
        .into_iter()
        .flatten()
        .filter(|socket| {
            let has_name = socket
                .get("name")
                .and_then(|value| value.as_str())
                .map(|name| !name.is_empty())
                .unwrap_or(false);
            let has_path = socket
                .get("path")
                .and_then(|value| value.as_str())
                .is_some();
            has_name && has_path
        })
        .cloned()
        .collect()
}

// ── Audit trail: durable persistence + query dispatch ────────────────────────

/// Convert a chain event into a durable footprint for the `timing_subvol`.
///
/// The full event is embedded under `metadata.audit_event` so the startup
/// rebuild can restore it losslessly, including the stored `event_hash` and
/// `prev_hash` that make the chain tamper-evident. The flat metadata keys
/// beside it exist for operators and tools grepping the timing directory
/// directly.
///
/// OSCAL subid: `evt.service.event-chain.persist@v1`
fn event_to_footprint(event: &ChainEvent) -> PluginFootprint {
    let mut metadata: HashMap<String, simd_json::OwnedValue> = HashMap::new();
    metadata.insert(
        "actor_id".to_string(),
        simd_json::OwnedValue::from(event.actor_id.as_str()),
    );
    metadata.insert(
        "capability_id".to_string(),
        simd_json::OwnedValue::from(event.capability_id.clone().unwrap_or_default()),
    );
    metadata.insert(
        "method_name".to_string(),
        simd_json::OwnedValue::from(event.method_name.clone().unwrap_or_default()),
    );
    metadata.insert(
        "event_id".to_string(),
        simd_json::OwnedValue::from(event.event_id),
    );
    metadata.insert(
        "event_hash".to_string(),
        simd_json::OwnedValue::from(event.event_hash.as_str()),
    );
    metadata.insert(
        "decision".to_string(),
        simd_json::OwnedValue::from(format!("{:?}", event.decision)),
    );
    // Lossless copy for replay. Serialized through serde_json (ChainEvent's
    // derive target) and re-parsed into simd_json for the footprint map.
    match serde_json::to_vec(event) {
        Ok(mut bytes) => match simd_json::to_owned_value(&mut bytes) {
            Ok(value) => {
                metadata.insert("audit_event".to_string(), value);
            }
            Err(error) => {
                tracing::warn!(%error, event_id = event.event_id, "audit event not replayable");
            }
        },
        Err(error) => {
            tracing::warn!(%error, event_id = event.event_id, "audit event not serializable");
        }
    }

    PluginFootprint {
        plugin_id: event.plugin_id.clone(),
        operation: event
            .method_name
            .clone()
            .unwrap_or_else(|| format!("{:?}", event.op)),
        timestamp: event.timestamp.timestamp_millis() as u64,
        data_hash: event.input_patch_hash.clone(),
        // The event hash is the timing file name, so one file per event.
        content_hash: event.event_hash.clone(),
        metadata,
        vector_features: vec![],
    }
}

/// Flatten a chain event into the plugin-surface record shape.
fn chain_event_to_record(event: &ChainEvent) -> AuditEventRecord {
    AuditEventRecord {
        event_id: event.event_id,
        event_hash: event.event_hash.clone(),
        prev_hash: event.prev_hash.clone(),
        timestamp: event.timestamp.to_rfc3339(),
        actor_id: event.actor_id.clone(),
        capability_id: event.capability_id.clone().unwrap_or_default(),
        plugin_id: event.plugin_id.clone(),
        method_name: event.method_name.clone().unwrap_or_default(),
        operation_type: format!("{:?}", event.op),
        target: event.target.clone(),
        tags_touched: event.tags_touched.clone(),
        decision: format!("{:?}", event.decision),
        input_patch_hash: event.input_patch_hash.clone(),
        result_effective_hash: event.result_effective_hash.clone().unwrap_or_default(),
    }
}

/// `blockchain.query_events` — paginated, filtered read of the audit trail.
///
/// Reads the same `EventChain` the gRPC `EventChainService.GetEvents` serves, so
/// the D-Bus/MCP path and the GUI path can never disagree.
///
/// OSCAL subid: `obs.service.blockchain.events.query@v1`
async fn dispatch_blockchain_query_events(
    event_chain: &Arc<RwLock<EventChain>>,
    args: &simd_json::OwnedValue,
) -> anyhow::Result<serde_json::Value> {
    let input: QueryEventsInput =
        serde_json::from_value(serde_json::to_value(args)?).unwrap_or_default();

    // Default 50, hard ceiling 100 — clamped silently, never unbounded (FR-4).
    let limit = input.limit.unwrap_or(50).clamp(1, 100) as usize;

    let chain = event_chain.read().await;
    let total_in_chain = chain.events().len() as u64;

    let decision_filter = input.decision.as_deref().map(str::to_ascii_lowercase);

    let mut matched: Vec<AuditEventRecord> = chain
        .events()
        .iter()
        .filter(|e| input.from_event_id.is_none_or(|id| e.event_id >= id))
        .filter(|e| input.to_event_id.is_none_or(|id| e.event_id <= id))
        .filter(|e| {
            input
                .plugin_id
                .as_ref()
                .is_none_or(|p| p.is_empty() || e.plugin_id == *p)
        })
        .filter(|e| match decision_filter.as_deref() {
            Some("allow") => e.decision == Decision::Allow,
            Some("deny") => e.decision == Decision::Deny,
            _ => true,
        })
        // One extra row reveals whether another page exists.
        .take(limit + 1)
        .map(chain_event_to_record)
        .collect();

    let has_more = matched.len() > limit;
    matched.truncate(limit);

    Ok(serde_json::to_value(QueryEventsOutput {
        events: matched,
        has_more,
        total_in_chain,
    })?)
}

/// `blockchain.verify_chain` — hash-chain integrity check over a range.
///
/// OSCAL subid: `obs.service.blockchain.chain.verify@v1`
async fn dispatch_blockchain_verify_chain(
    event_chain: &Arc<RwLock<EventChain>>,
    args: &simd_json::OwnedValue,
) -> anyhow::Result<serde_json::Value> {
    let input: VerifyChainInput =
        serde_json::from_value(serde_json::to_value(args)?).unwrap_or_default();

    let chain = event_chain.read().await;
    let result = chain.verify_range(
        input.from_event_id.unwrap_or(0),
        input.to_event_id.unwrap_or(0),
    );

    Ok(serde_json::to_value(VerifyChainOutput {
        valid: result.valid,
        events_verified: result.events_verified as u64,
        errors: result.errors,
    })?)
}

/// Execute schema-declared rtnetlink methods through the native netlink
/// implementation. Namespace-local sockets are created only after the
/// dedicated worker enters the target namespace.
async fn dispatch_rtnetlink_method(
    method: &str,
    args: &simd_json::OwnedValue,
) -> anyhow::Result<serde_json::Value> {
    use op_plugins::state_plugins::rtnetlink::{
        AddIpv4AddressInput, AddRouteInput, MoveLinkInput, RtnetlinkMutationOutput,
        SetDefaultRouteInput, SetLinkStateInput, SetMacAddressInput,
    };

    fn result(
        operation: &str,
        interface: String,
        netns_pid: Option<u32>,
    ) -> anyhow::Result<serde_json::Value> {
        Ok(serde_json::to_value(RtnetlinkMutationOutput {
            operation: operation.to_string(),
            interface,
            netns_pid,
        })?)
    }

    fn ignore_exists(error: anyhow::Error) -> anyhow::Result<()> {
        let message = error.to_string().to_ascii_lowercase();
        if message.contains("exist") {
            Ok(())
        } else {
            Err(error)
        }
    }

    let json = serde_json::to_value(args)?;
    match method {
        "move_link" => {
            let input: MoveLinkInput = serde_json::from_value(json)?;
            op_network::rtnetlink::move_link_to_netns(&input.iface_name, input.netns_pid).await?;
            result("move_link", input.iface_name, Some(input.netns_pid))
        }
        "set_link_state" => {
            let input: SetLinkStateInput = serde_json::from_value(json)?;
            let is_up = match input.state.as_str() {
                "up" => true,
                "down" => false,
                other => anyhow::bail!("invalid link state '{other}'; expected 'up' or 'down'"),
            };
            if let Some(pid) = input.netns_pid {
                op_network::rtnetlink::set_link_state_in_netns(pid, &input.name, is_up).await?;
            } else if is_up {
                op_network::rtnetlink::link_up(&input.name).await?;
            } else {
                op_network::rtnetlink::link_down(&input.name).await?;
            }
            result("set_link_state", input.name, input.netns_pid)
        }
        "add_ipv4_address" => {
            let input: AddIpv4AddressInput = serde_json::from_value(json)?;
            let (address, prefix) = input
                .address
                .rsplit_once('/')
                .ok_or_else(|| anyhow::anyhow!("address must use IPv4 CIDR notation"))?;
            let prefix: u8 = prefix.parse().context("invalid IPv4 prefix")?;
            if prefix > 32 {
                anyhow::bail!("IPv4 prefix must be between 0 and 32");
            }
            let operation = if let Some(pid) = input.netns_pid {
                op_network::rtnetlink::add_ipv4_address_in_netns(pid, &input.name, address, prefix)
                    .await
            } else {
                op_network::rtnetlink::add_ipv4_address(&input.name, address, prefix).await
            };
            if let Err(error) = operation {
                ignore_exists(error)?;
            }
            result("add_ipv4_address", input.name, input.netns_pid)
        }
        "set_mac_address" => {
            let input: SetMacAddressInput = serde_json::from_value(json)?;
            op_network::rtnetlink::set_mac_address(&input.name, &input.mac).await?;
            result("set_mac_address", input.name, None)
        }
        "set_default_route" => {
            let input: SetDefaultRouteInput = serde_json::from_value(json)?;
            let operation = if let Some(pid) = input.netns_pid {
                op_network::rtnetlink::add_default_route_in_netns(pid, &input.name, &input.gateway)
                    .await
            } else {
                op_network::rtnetlink::add_default_route(&input.name, &input.gateway).await
            };
            if let Err(error) = operation {
                ignore_exists(error)?;
            }
            result("set_default_route", input.name, input.netns_pid)
        }
        "add_route" => {
            let input: AddRouteInput = serde_json::from_value(json)?;
            let operation = if let Some(pid) = input.netns_pid {
                op_network::rtnetlink::add_ipv4_route_in_netns(
                    pid,
                    &input.destination,
                    input.gateway.as_deref(),
                    &input.interface,
                    input.table,
                )
                .await
            } else {
                op_network::rtnetlink::add_ipv4_route(
                    &input.destination,
                    input.gateway.as_deref(),
                    &input.interface,
                    input.table,
                )
                .await
            };
            if let Err(error) = operation {
                ignore_exists(error)?;
            }
            result("add_route", input.interface, input.netns_pid)
        }
        _ => Err(anyhow::anyhow!(
            "rtnetlink.{method} is schema-declared but has no native runtime dispatcher"
        )),
    }
}

/// Execute rovs_commands methods via OVSDB proxy
async fn dispatch_rovs_commands_method(
    ovsdb: &op_network::rovs_proxy::OvsdbDbusClient,
    method: &str,
    args: &simd_json::OwnedValue,
) -> anyhow::Result<serde_json::Value> {
    match method {
        "create_bridge" => {
            let bridge_name = args
                .get("bridge_name")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("bridge_name required"))?;
            ovsdb.create_bridge(bridge_name).await?;
            Ok(serde_json::json!({"created": bridge_name}))
        }
        "delete_bridge" => {
            let bridge_name = args
                .get("bridge_name")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("bridge_name required"))?;
            ovsdb.delete_bridge(bridge_name).await?;
            Ok(serde_json::json!({"deleted": bridge_name}))
        }
        "add_port" => {
            let bridge_name = args
                .get("bridge_name")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("bridge_name required"))?;
            let port_name = args
                .get("port_name")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("port_name required"))?;
            let interface_type = args
                .get("interface_type")
                .and_then(|v| v.as_str())
                .unwrap_or("internal");
            if interface_type.is_empty() {
                return Err(anyhow::anyhow!("interface_type must not be empty"));
            }
            ovsdb
                .add_port_with_type(bridge_name, port_name, Some(interface_type))
                .await?;
            Ok(serde_json::json!({
                "added": port_name,
                "to": bridge_name,
                "interface_type": interface_type,
            }))
        }
        "remove_port" => {
            let bridge_name = args
                .get("bridge_name")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("bridge_name required"))?;
            let port_name = args
                .get("port_name")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("port_name required"))?;
            ovsdb.delete_port(bridge_name, port_name).await?;
            Ok(serde_json::json!({"removed": port_name, "from": bridge_name}))
        }
        "list_bridges" => {
            let bridges = ovsdb.list_bridges().await?;
            Ok(serde_json::json!(bridges))
        }
        "list_ports" => {
            let bridge_name = args
                .get("bridge_name")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("bridge_name required"))?;
            let ports = ovsdb.list_bridge_ports(bridge_name).await?;
            Ok(serde_json::json!(ports))
        }
        "list_dbs" => {
            let dbs = ovsdb.list_dbs().await?;
            Ok(serde_json::json!(dbs))
        }
        _ => Err(anyhow::anyhow!("unknown rovs_commands method: {}", method)),
    }
}

/// Execute the schema-declared OVSDB bridge methods used by canonical
/// `org.opdbus.v1.plugins` compatibility clients.
async fn dispatch_ovsdb_bridge_method(
    ovsdb: &op_network::rovs_proxy::OvsdbDbusClient,
    method: &str,
    args: &simd_json::OwnedValue,
) -> anyhow::Result<serde_json::Value> {
    match method {
        "list_dbs" => Ok(serde_json::json!(ovsdb.list_dbs().await?)),
        "get_schema" => Ok(ovsdb.get_schema().await?),
        "transact" => {
            let operations = args
                .get("operations")
                .ok_or_else(|| anyhow::anyhow!("operations required"))?
                .clone();
            Ok(ovsdb.transact_simd(operations).await?)
        }
        _ => Err(anyhow::anyhow!(
            "ovsdb_bridge.{method} is schema-declared but has no runtime dispatcher"
        )),
    }
}

/// Dispatch for the `xray` plugin's schema-declared methods. Only `get_stats`
/// is backed by real behavior so far — it calls xray-core's own StatsService
/// over the commander UDS (see `op_xray_daemon::commander_client`). The
/// other declared methods (`add_user`, `remove_user`, `add_inbound`,
/// `restart`, `start_trace`/`end_trace`/`record_span`) are schema-declared
/// but not yet implemented; they fail closed rather than silently
/// succeeding or falling through to the generic echo.
async fn dispatch_xray_method(
    method: &str,
    args: &serde_json::Value,
) -> anyhow::Result<serde_json::Value> {
    match method {
        "get_stats" => {
            let name = args
                .get("name")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("name required"))?;
            let mut client = op_xray_daemon::commander_client::stats_client(
                op_xray_daemon::commander_client::DEFAULT_API_SOCKET,
            )
            .await
            .context("connecting to xray commander API socket")?;
            let resp = client
                .get_stats(op_xray_daemon::commander_client::stats::GetStatsRequest {
                    name: name.to_string(),
                    reset: false,
                })
                .await
                .context("xray StatsService.GetStats")?
                .into_inner();
            let stat = resp
                .stat
                .ok_or_else(|| anyhow::anyhow!("no such stat counter: {name}"))?;
            Ok(serde_json::json!({ "name": stat.name, "value": stat.value }))
        }
        "restart" => {
            // Reload (SIGHUP), not a hard kill+respawn: the `xray` container's
            // own service manager already supervises the process; a config
            // reload is the safe, sanctioned action here (see op-plugins::xray's
            // apply_state, which uses the same pattern). No Command::new
            // subprocess — signals the real PID directly via /proc + nix.
            let pids = find_xray_pids();
            if pids.is_empty() {
                return Err(anyhow::anyhow!("no running xray process found"));
            }
            let mut reloaded = Vec::new();
            for pid in pids {
                nix::sys::signal::kill(pid, nix::sys::signal::Signal::SIGHUP)
                    .with_context(|| format!("sending SIGHUP to xray pid {pid}"))?;
                reloaded.push(pid.as_raw());
            }
            Ok(serde_json::json!({ "reloaded_pids": reloaded }))
        }
        "add_user" | "remove_user" | "add_inbound" | "start_trace" | "end_trace"
        | "record_span" => Err(anyhow::anyhow!(
            "xray.{method} is schema-declared but not yet implemented"
        )),
        _ => Err(anyhow::anyhow!("unknown xray method: {}", method)),
    }
}

/// Find running `xray` process PIDs via `/proc` — no `pgrep`/`pkill`
/// subprocess spawning. Mirrors `op_plugins::state_plugins::xray`'s private
/// helper of the same shape; kept local since it's a few lines and the two
/// crates don't otherwise share process-inspection utilities.
fn find_xray_pids() -> Vec<nix::unistd::Pid> {
    let mut pids = Vec::new();
    let Ok(entries) = std::fs::read_dir("/proc") else {
        return pids;
    };
    for entry in entries.flatten() {
        let Ok(pid) = entry.file_name().to_string_lossy().parse::<i32>() else {
            continue;
        };
        if let Ok(comm) = std::fs::read_to_string(entry.path().join("comm")) {
            if comm.trim() == "xray" {
                pids.push(nix::unistd::Pid::from_raw(pid));
            }
        }
    }
    pids
}

/// Dispatch a `cognitive_mcp` schema method to the cognitive tool registry.
///
/// OSCAL subid: mut.service.cognitive-mcp.dispatch@v1
///
/// Phase 1 transport is an HTTP loopback to `op-cognitive-mcp`'s MCP endpoint. The
/// bridge remains the only authorization door: the method-existence gate, arg
/// validation, capability check and event-chain append have all already happened in
/// `dispatch_method_call` before this function is reached.
///
/// Phase 2 replaces the loopback with an in-process `ToolRegistry::execute` call and
/// retires the `:3003` listener. See
/// `.kiro/specs/cognitive-mcp-only-door-phase2/`.
async fn dispatch_cognitive_mcp_method(
    method: &str,
    args: &serde_json::Value,
) -> anyhow::Result<serde_json::Value> {
    // Plugin-local methods answer from published state; no executor hop needed.
    match method {
        "get_config" | "get_health" => {
            let mut bytes = op_core::projection_shm::read_projection_bytes("cognitive_mcp")
                .ok_or_else(|| anyhow::anyhow!("cognitive_mcp projection not available"))?;
            let value = simd_json::to_owned_value(&mut bytes)
                .map_err(|e| anyhow::anyhow!("cognitive_mcp projection is not valid JSON: {e}"))?;
            return Ok(serde_json::to_value(&value)?);
        }
        "set_config" | "restart_service" => {
            // These belong to the plugin's own apply_state path, which is reached
            // through StatePlugin rather than the tool registry. Acknowledge without
            // fabricating a result so callers can distinguish "accepted" from "done".
            return Ok(serde_json::json!({
                "acknowledged": true,
                "method": method,
                "note": "handled by cognitive_mcp apply_state; not a tool-registry call",
            }));
        }
        _ => {}
    }

    // `list_tools` is an MCP *protocol* method (`tools/list`), not an entry in the
    // tool registry, so it cannot go through `tools/call`.
    if method == "list_tools" {
        return cognitive_tools_list().await;
    }

    let (tool_name, tool_args) = map_schema_method_to_tool(method, args)?;
    let result = call_cognitive_tool(&tool_name, &tool_args).await?;
    Ok(result)
}

/// Translate a `cognitive_mcp` schema method name into a live tool-registry call.
///
/// The schema method names do not map one-to-one onto registry tool names: the
/// registry exposes a single `cognitive_memory` tool selected by an `operation`
/// field, so the memory methods inject that field rather than existing as separate
/// tools. `invoke_tool` bypasses the table entirely and names its tool directly.
fn map_schema_method_to_tool(
    method: &str,
    args: &serde_json::Value,
) -> anyhow::Result<(String, serde_json::Value)> {
    let base = if args.is_object() {
        args.clone()
    } else {
        serde_json::json!({})
    };

    let with_field = |key: &str, value: &str| -> serde_json::Value {
        let mut v = base.clone();
        if let Some(obj) = v.as_object_mut() {
            obj.insert(
                key.to_string(),
                serde_json::Value::String(value.to_string()),
            );
        }
        v
    };

    match method {
        // Memory methods all resolve to the one `cognitive_memory` tool.
        "memory_store" => Ok(("cognitive_memory".into(), with_field("operation", "store"))),
        "memory_query" => Ok(("cognitive_memory".into(), with_field("operation", "query"))),
        "memory_retrieve" => Ok((
            "cognitive_memory".into(),
            with_field("operation", "retrieve"),
        )),
        "memory_delete" => Ok(("cognitive_memory".into(), with_field("operation", "delete"))),
        "memory_list_namespaces" => Ok((
            "cognitive_memory".into(),
            with_field("operation", "list_namespaces"),
        )),
        // Code retrieval / indexing.
        "code_search" => Ok(("search_blob_vectors".into(), base)),
        "code_index" => Ok(("refresh_blob_vectors".into(), base)),
        "code_context" => Ok((
            "search_blob_vectors".into(),
            with_field("activity_type", "query"),
        )),
        // Gemini question answering: the tool names the field `question`.
        "gemini_query" => {
            let mut v = base.clone();
            if let Some(obj) = v.as_object_mut() {
                if let Some(q) = obj.remove("query") {
                    obj.insert("question".to_string(), q);
                }
            }
            Ok(("ask_question".into(), v))
        }
        "register_tool" => Ok(("register_tool".into(), base)),
        // Generic door: the caller names the tool.
        "invoke_tool" => {
            let tool_name = args
                .get("tool_name")
                .and_then(|v| v.as_str())
                .ok_or_else(|| anyhow::anyhow!("invoke_tool: missing required field 'tool_name'"))?
                .to_string();
            if tool_name.is_empty() {
                return Err(anyhow::anyhow!(
                    "invoke_tool: 'tool_name' must not be empty"
                ));
            }
            let tool_args = args
                .get("arguments")
                .cloned()
                .unwrap_or_else(|| serde_json::json!({}));
            Ok((tool_name, tool_args))
        }
        other => Err(anyhow::anyhow!(
            "cognitive_mcp method '{other}' has no tool-registry mapping"
        )),
    }
}

/// Shared HTTP client for the cognitive MCP loopback.
///
/// Built once: a fresh `Client` per call would leak a connection pool and defeat
/// keep-alive on what is a hot path.
static COGNITIVE_MCP_HTTP: std::sync::OnceLock<reqwest::Client> = std::sync::OnceLock::new();

fn cognitive_mcp_http() -> &'static reqwest::Client {
    COGNITIVE_MCP_HTTP.get_or_init(|| {
        reqwest::Client::builder()
            .timeout(std::time::Duration::from_secs(120))
            .build()
            .unwrap_or_else(|_| reqwest::Client::new())
    })
}

/// MCP endpoint of the local cognitive service.
///
/// Overridable so the bridge can follow a relocated listener without a rebuild.
fn cognitive_mcp_endpoint() -> String {
    std::env::var("COGNITIVE_MCP_MCP_URL")
        .unwrap_or_else(|_| "http://10.200.0.2:3003/mcp".to_string())
}

/// Send the MCP `initialize` handshake.
///
/// The cognitive MCP server rejects `tools/call` with "Server not initialized" until
/// this has been sent. Initialization is server-side state, so it survives across
/// requests but is lost whenever `op-cognitive-mcp` restarts — which is why callers
/// treat it as a recoverable condition rather than doing it once at startup.
async fn cognitive_mcp_initialize() -> anyhow::Result<()> {
    let endpoint = cognitive_mcp_endpoint();
    let request = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 0,
        "method": "initialize",
        "params": {},
    });

    let response = cognitive_mcp_http()
        .post(&endpoint)
        .header("Content-Type", "application/json")
        .header("X-Ghostbridge-Footprint", "op-grpc-bridge")
        .header("X-Ghostbridge-Trace-ID", "bridge-dispatch")
        .json(&request)
        .send()
        .await
        .with_context(|| format!("cognitive_mcp initialize POST {endpoint}"))?;

    if !response.status().is_success() {
        return Err(anyhow::anyhow!(
            "cognitive_mcp initialize returned HTTP {}",
            response.status()
        ));
    }
    Ok(())
}

/// Issue one `tools/call` and return the raw JSON-RPC envelope.
async fn cognitive_tools_call_raw(
    tool_name: &str,
    tool_args: &serde_json::Value,
) -> anyhow::Result<serde_json::Value> {
    let endpoint = cognitive_mcp_endpoint();
    let request = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/call",
        "params": { "name": tool_name, "arguments": tool_args },
    });

    let response = cognitive_mcp_http()
        .post(&endpoint)
        .header("Content-Type", "application/json")
        // The interceptor on the direct listener expects these; the authoritative
        // authorization decision was already made by the bridge before dispatch.
        .header("X-Ghostbridge-Footprint", "op-grpc-bridge")
        .header("X-Ghostbridge-Trace-ID", "bridge-dispatch")
        .json(&request)
        .send()
        .await
        .with_context(|| format!("cognitive_mcp loopback POST {endpoint}"))?;

    let status = response.status();
    let body = response
        .text()
        .await
        .context("reading cognitive_mcp loopback response body")?;

    if !status.is_success() {
        return Err(anyhow::anyhow!(
            "cognitive_mcp loopback returned HTTP {status}: {body}"
        ));
    }

    serde_json::from_str(&body)
        .with_context(|| format!("cognitive_mcp returned non-JSON body: {body}"))
}

/// Invoke one tool over the MCP `tools/call` JSON-RPC method and unwrap the result.
///
/// Performs the `initialize` handshake lazily: rather than initializing once at bridge
/// startup (which would break the first call after any `op-cognitive-mcp` restart), a
/// "not initialized" error triggers one initialize and a single retry.
async fn call_cognitive_tool(
    tool_name: &str,
    tool_args: &serde_json::Value,
) -> anyhow::Result<serde_json::Value> {
    let mut envelope = cognitive_tools_call_raw(tool_name, tool_args).await?;

    if mcp_needs_initialize(&envelope) {
        cognitive_mcp_initialize().await?;
        envelope = cognitive_tools_call_raw(tool_name, tool_args).await?;
    }

    if let Some(error) = envelope.get("error") {
        let message = error
            .get("message")
            .and_then(|m| m.as_str())
            .unwrap_or("unknown MCP error");
        return Err(anyhow::anyhow!("tool '{tool_name}' failed: {message}"));
    }

    envelope.get("result").cloned().ok_or_else(|| {
        anyhow::anyhow!("cognitive_mcp response had neither 'result' nor 'error': {envelope}")
    })
}

/// Enumerate the live tool registry via the MCP `tools/list` protocol method.
///
/// Distinct from `call_cognitive_tool`: `tools/list` is a protocol method rather than a
/// registry entry, so routing the `list_tools` schema method through `tools/call` would
/// (and did) fail with "Tool not found: list_tools".
async fn cognitive_tools_list() -> anyhow::Result<serde_json::Value> {
    let endpoint = cognitive_mcp_endpoint();
    let request = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/list",
        "params": {},
    });

    let post = || async {
        let response = cognitive_mcp_http()
            .post(&endpoint)
            .header("Content-Type", "application/json")
            .header("X-Ghostbridge-Footprint", "op-grpc-bridge")
            .header("X-Ghostbridge-Trace-ID", "bridge-dispatch")
            .json(&request)
            .send()
            .await
            .with_context(|| format!("cognitive_mcp tools/list POST {endpoint}"))?;

        let status = response.status();
        let body = response
            .text()
            .await
            .context("reading cognitive_mcp tools/list response body")?;
        if !status.is_success() {
            return Err(anyhow::anyhow!(
                "cognitive_mcp tools/list returned HTTP {status}: {body}"
            ));
        }
        serde_json::from_str::<serde_json::Value>(&body)
            .with_context(|| format!("cognitive_mcp tools/list returned non-JSON body: {body}"))
    };

    let mut envelope = post().await?;
    if mcp_needs_initialize(&envelope) {
        cognitive_mcp_initialize().await?;
        envelope = post().await?;
    }

    if let Some(error) = envelope.get("error") {
        let message = error
            .get("message")
            .and_then(|m| m.as_str())
            .unwrap_or("unknown MCP error");
        return Err(anyhow::anyhow!("tools/list failed: {message}"));
    }

    envelope
        .get("result")
        .cloned()
        .ok_or_else(|| anyhow::anyhow!("cognitive_mcp tools/list response had no 'result'"))
}

/// True when the envelope is the server's "call initialize first" rejection.
fn mcp_needs_initialize(envelope: &serde_json::Value) -> bool {
    envelope
        .get("error")
        .and_then(|e| e.get("message"))
        .and_then(|m| m.as_str())
        .is_some_and(|m| m.contains("not initialized"))
}

/// Parse createunixsocket arguments. Accepts either a JSON array
/// `[name, [ports...]]` or an object `{ "name": "...", "ports": [...] }`.
/// `ports` may be a JSON array of numbers or a CSV string ("6334" / "6334,8080").
fn parse_socket_args(value: &simd_json::OwnedValue) -> (String, Vec<u16>) {
    if let Some(obj) = value.as_object() {
        return parse_socket_arg_object(obj);
    }
    if let Some(arr) = value.as_array() {
        if arr.len() == 1 {
            if let Some(obj) = arr.first().and_then(|v| v.as_object()) {
                return parse_socket_arg_object(obj);
            }
        }
        let name = arr
            .first()
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let ports = parse_ports_value(arr.get(1));
        return (name, ports);
    }
    (String::new(), Vec::new())
}

fn parse_socket_arg_object(obj: &simd_json::value::owned::Object) -> (String, Vec<u16>) {
    let name = obj
        .get("name")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let ports = parse_ports_value(obj.get("ports"));
    (name, ports)
}

fn parse_ports_value(value: Option<&simd_json::OwnedValue>) -> Vec<u16> {
    let Some(v) = value else {
        return Vec::new();
    };
    if let Some(arr) = v.as_array() {
        return arr
            .iter()
            .filter_map(parse_port_number)
            .map(|n| n as u16)
            .collect();
    }
    if let Some(s) = v.as_str() {
        return s
            .split(',')
            .filter_map(|p| p.trim().parse::<u16>().ok())
            .collect();
    }
    if let Some(n) = parse_port_number(v) {
        return vec![n as u16];
    }
    Vec::new()
}

fn parse_port_number(value: &simd_json::OwnedValue) -> Option<u64> {
    value
        .as_u64()
        .or_else(|| value.as_i64().and_then(|n| (n >= 0).then_some(n as u64)))
        .or_else(|| {
            value.as_f64().and_then(|n| {
                (n.is_finite() && n >= 0.0 && n <= u16::MAX as f64).then_some(n as u64)
            })
        })
}

//! gRPC Client - For D-Bus → remote gRPC calls
//!
//! Allows local D-Bus services to call remote gRPC endpoints,
//! enabling distributed operation-dbus deployments.

use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;

use prost_types::{value::Kind as ProstKind, Struct as ProstStruct, Value as ProstValue};
use tokio::sync::RwLock;
use tonic::metadata::MetadataValue;
use tonic::transport::{Channel, Endpoint};
use tonic::Request;
use tracing::info;

use crate::proto::{
    event_chain_service_client::EventChainServiceClient,
    plugin_service_client::PluginServiceClient, state_sync_client::StateSyncClient,
    CallMethodRequest, GetStateRequest, MutateRequest, OperationType as ProtoOperationType,
    SubscribeEventsRequest, SubscribeRequest,
};
use op_grpc_adapters::proto::{
    execute_command_request::Command as ExecuteNetclientCommand,
    netmaker_service_client::NetmakerServiceClient, ConnectRequest, DisconnectRequest,
    ExecuteCommandRequest, ExecuteCommandResponse, HealthRequest, HealthResponse, InstallRequest,
    JoinNetworkRequest, LeaveNetworkRequest, ListRequest, PeersRequest, PingRequest, PullRequest,
    PushRequest, RegisterRequest, RestartServiceRequest, ServerRequest, UninstallRequest,
    UseRequest, VersionRequest,
};

/// Dedicated loopback endpoint for the Netmaker adapter UDS bridge.
pub const DEFAULT_NETMAKER_ADAPTER_ADDR: &str = "http://127.0.0.1:50061";

/// Build a Netmaker request that is always authenticated with the local
/// Ghostbridge identity. The `?` deliberately expands in the calling RPC so
/// an unreadable/invalid identity fails before any adapter request is sent.
macro_rules! authenticated_netmaker_request {
    ($message:expr) => {{
        let mut request = Request::new($message);
        attach_ghostbridge_metadata(&mut request)?;
        request
    }};
}

/// Configuration for a remote gRPC endpoint
#[derive(Debug, Clone)]
pub struct RemoteEndpoint {
    pub address: String,
    pub tls_enabled: bool,
    pub connect_timeout: Duration,
    pub request_timeout: Duration,
}

/// Caller-supplied Ghostbridge identity forwarded by an HTTP compatibility
/// adapter into the canonical gRPC method call.
#[derive(Debug, Clone)]
pub struct GhostbridgeCallMetadata {
    pub footprint: String,
    pub trace_id: Option<String>,
    pub wireguard_pubkey: Option<String>,
}

impl Default for RemoteEndpoint {
    fn default() -> Self {
        Self {
            address: "http://127.0.0.1:8090".to_string(),
            tls_enabled: false,
            connect_timeout: Duration::from_secs(5),
            request_timeout: Duration::from_secs(30),
        }
    }
}

/// gRPC client pool for connecting to remote Operation services
pub struct GrpcClientPool {
    /// Map of endpoint address to channel
    channels: RwLock<HashMap<String, Channel>>,
    /// Default endpoint configuration
    default_config: RemoteEndpoint,
}

impl Default for GrpcClientPool {
    fn default() -> Self {
        Self::new()
    }
}

impl GrpcClientPool {
    pub fn new() -> Self {
        Self {
            channels: RwLock::new(HashMap::new()),
            default_config: RemoteEndpoint::default(),
        }
    }

    pub fn with_default_config(config: RemoteEndpoint) -> Self {
        Self {
            channels: RwLock::new(HashMap::new()),
            default_config: config,
        }
    }

    /// Get or create a channel to the specified address (supports comma-separated endpoints for load balancing)
    async fn get_channel(&self, address: &str) -> Result<Channel, GrpcClientError> {
        {
            let channels = self.channels.read().await;
            if let Some(channel) = channels.get(address) {
                return Ok(channel.clone());
            }
        }

        let addrs: Vec<&str> = address
            .split(',')
            .map(|s| s.trim())
            .filter(|s| !s.is_empty())
            .collect();

        let channel = if addrs.len() > 1 {
            // Native Tonic Load Balancing
            let endpoints = addrs
                .into_iter()
                .map(|addr| {
                    Endpoint::from_shared(addr.to_string()).map(|e| {
                        e.connect_timeout(self.default_config.connect_timeout)
                            .timeout(self.default_config.request_timeout)
                    })
                })
                .collect::<Result<Vec<_>, _>>()
                .map_err(|e| {
                    GrpcClientError::ConnectionFailed(format!("Invalid endpoint: {}", e))
                })?;

            Channel::balance_list(endpoints.into_iter())
        } else {
            // Single endpoint
            let endpoint = Endpoint::from_shared(address.to_string())
                .map_err(|e| GrpcClientError::ConnectionFailed(e.to_string()))?
                .connect_timeout(self.default_config.connect_timeout)
                .timeout(self.default_config.request_timeout);

            endpoint
                .connect()
                .await
                .map_err(|e| GrpcClientError::ConnectionFailed(e.to_string()))?
        };

        {
            let mut channels = self.channels.write().await;
            channels.insert(address.to_string(), channel.clone());
        }

        info!("Connected to remote gRPC endpoint(s): {}", address);
        Ok(channel)
    }

    /// Get a Plugin service client
    pub async fn plugin_service_client(
        &self,
        address: &str,
    ) -> Result<PluginServiceClient<Channel>, GrpcClientError> {
        let channel = self.get_channel(address).await?;
        Ok(PluginServiceClient::new(channel))
    }

    /// Get a StateSync service client
    pub async fn state_sync_client(
        &self,
        address: &str,
    ) -> Result<StateSyncClient<Channel>, GrpcClientError> {
        let channel = self.get_channel(address).await?;
        Ok(StateSyncClient::new(channel))
    }

    /// Get an EventChain service client
    pub async fn event_chain_client(
        &self,
        address: &str,
    ) -> Result<EventChainServiceClient<Channel>, GrpcClientError> {
        let channel = self.get_channel(address).await?;
        Ok(EventChainServiceClient::new(channel))
    }

    /// Get a Netmaker adapter client.
    pub async fn netmaker_client(
        &self,
        address: &str,
    ) -> Result<NetmakerServiceClient<Channel>, GrpcClientError> {
        let channel = self.get_channel(address).await?;
        Ok(NetmakerServiceClient::new(channel))
    }

    /// Close all connections
    pub async fn close_all(&self) {
        let mut channels = self.channels.write().await;
        channels.clear();
        info!("Closed all gRPC client connections");
    }
}

/// High-level client for remote Operation services
#[allow(dead_code)]
pub struct RemoteOperationClient {
    pool: Arc<GrpcClientPool>,
    default_address: String,
    netmaker_address: String,
    client_id: String,
}

impl RemoteOperationClient {
    /// Backward-compatible constructor: both service families use `address`.
    pub fn new(pool: Arc<GrpcClientPool>, address: &str, client_id: &str) -> Self {
        Self {
            pool,
            default_address: address.to_string(),
            netmaker_address: address.to_string(),
            client_id: client_id.to_string(),
        }
    }

    /// Construct a client with an explicit dedicated Netmaker adapter endpoint.
    pub fn new_with_netmaker_address(
        pool: Arc<GrpcClientPool>,
        address: &str,
        netmaker_address: &str,
        client_id: &str,
    ) -> Self {
        Self {
            pool,
            default_address: address.to_string(),
            netmaker_address: netmaker_address.to_string(),
            client_id: client_id.to_string(),
        }
    }

    /// Construct a client using `NETMAKER_ADAPTER_ADDR`, defaulting to the
    /// fixed host bridge at `http://127.0.0.1:50061`.
    pub fn new_with_netmaker_env(
        pool: Arc<GrpcClientPool>,
        address: &str,
        client_id: &str,
    ) -> Self {
        let netmaker_address = std::env::var("NETMAKER_ADAPTER_ADDR")
            .unwrap_or_else(|_| DEFAULT_NETMAKER_ADAPTER_ADDR.to_string());
        Self::new_with_netmaker_address(pool, address, &netmaker_address, client_id)
    }

    /// Override the dedicated Netmaker endpoint in builder style.
    pub fn with_netmaker_address(mut self, address: impl Into<String>) -> Self {
        self.netmaker_address = address.into();
        self
    }

    /// Get state from a remote endpoint
    pub async fn get_state(
        &self,
        plugin_id: &str,
        object_path: &str,
    ) -> Result<simd_json::OwnedValue, GrpcClientError> {
        let mut client = self.pool.state_sync_client(&self.default_address).await?;

        let mut request = Request::new(GetStateRequest {
            plugin_id: plugin_id.to_string(),
            object_path: object_path.to_string(),
        });
        attach_ghostbridge_metadata(&mut request)?;

        let response = client
            .get_state(request)
            .await
            .map_err(|e| GrpcClientError::RequestFailed(e.to_string()))?;

        let resp = response.into_inner();
        let state = resp.state.unwrap_or_default();
        Ok(prost_struct_to_simd(&state))
    }

    /// Set state on a remote endpoint (apply patch)
    pub async fn set_state(
        &self,
        plugin_id: &str,
        object_path: &str,
        state: simd_json::OwnedValue,
        actor_id: &str,
        capability_id: &str,
    ) -> Result<SetStateResult, GrpcClientError> {
        let mut client = self.pool.state_sync_client(&self.default_address).await?;

        let mut request = Request::new(MutateRequest {
            plugin_id: plugin_id.to_string(),
            object_path: object_path.to_string(),
            operation: ProtoOperationType::ApplyPatch as i32,
            member_name: String::new(),
            value: Some(simd_to_prost_value(&state)),
            actor_id: actor_id.to_string(),
            capability_id: capability_id.to_string(),
            idempotency_key: uuid::Uuid::new_v4().to_string(),
        });
        attach_ghostbridge_metadata(&mut request)?;

        let response = client
            .mutate(request)
            .await
            .map_err(|e| GrpcClientError::RequestFailed(e.to_string()))?;

        let resp = response.into_inner();
        if !resp.success {
            if let Some(err) = resp.error {
                return Err(GrpcClientError::RemoteError {
                    code: format!("{}", err.code),
                    message: err.message,
                });
            }
            return Err(GrpcClientError::RemoteError {
                code: "UNKNOWN".to_string(),
                message: "mutation failed".to_string(),
            });
        }

        Ok(SetStateResult {
            event_id: resp.event_id,
            effective_hash: resp.effective_hash,
        })
    }

    /// Call a method on a remote endpoint
    #[allow(clippy::too_many_arguments)]
    pub async fn call_method(
        &self,
        plugin_id: &str,
        object_path: &str,
        interface_name: &str,
        method_name: &str,
        arguments: Vec<simd_json::OwnedValue>,
        actor_id: &str,
        capability_id: &str,
    ) -> Result<simd_json::OwnedValue, GrpcClientError> {
        let mut client = self
            .pool
            .plugin_service_client(&self.default_address)
            .await?;

        let arguments = arguments
            .iter()
            .map(simd_to_prost_value)
            .collect::<Vec<_>>();

        let mut request = Request::new(CallMethodRequest {
            plugin_id: plugin_id.to_string(),
            object_path: object_path.to_string(),
            interface_name: interface_name.to_string(),
            method_name: method_name.to_string(),
            arguments,
            actor_id: actor_id.to_string(),
            capability_id: capability_id.to_string(),
        });
        attach_ghostbridge_metadata(&mut request)?;

        let response = client
            .call_method(request)
            .await
            .map_err(|e| GrpcClientError::RequestFailed(e.to_string()))?;

        let resp = response.into_inner();
        if !resp.success {
            if let Some(err) = resp.error {
                return Err(GrpcClientError::RemoteError {
                    code: format!("{}", err.code),
                    message: err.message,
                });
            }
            return Err(GrpcClientError::RemoteError {
                code: "UNKNOWN".to_string(),
                message: "call failed".to_string(),
            });
        }

        if let Some(result) = resp.result {
            Ok(prost_value_to_simd(&result))
        } else {
            Ok(simd_json::json!(null))
        }
    }

    /// Call a method while preserving the Ghostbridge identity supplied by an
    /// outer transport adapter. This keeps HTTP on op-web while capability
    /// enforcement remains in the bridge's canonical gRPC method pipeline.
    #[allow(clippy::too_many_arguments)]
    pub async fn call_method_with_metadata(
        &self,
        plugin_id: &str,
        object_path: &str,
