#[cfg(test)]
mod authoritative_query_tests {
    use super::*;
    use op_network::controller::SwitchFlowStats;

    #[test]
    fn normalizes_phase1_udp_switch_flow() {
        let flow = OpenFlowPlugin::switch_flow_to_entry(SwitchFlowStats {
            table: 0,
            priority: 100,
            cookie: 0x4e4d4b0000000002,
            matches: "in_port=7,eth_type=0x0800,ip_proto=17,udp_dst=51820".to_string(),
            actions: "NORMAL".to_string(),
            packet_count: 4,
            byte_count: 512,
            idle_timeout: 0,
            hard_timeout: 0,
        });

        assert_eq!(flow.match_fields.get("in_port"), Some(&"7".to_string()));
        assert_eq!(flow.match_fields.get("udp"), Some(&String::new()));
        assert_eq!(flow.match_fields.get("tp_dst"), Some(&"51820".to_string()));
        assert_eq!(flow.actions, vec![FlowAction::Normal]);
        assert_eq!(flow.cookie, Some(0x4e4d4b0000000002));
    }

    #[test]
    fn normalizes_phase1_arp_and_drop_switch_flows() {
        let arp = OpenFlowPlugin::switch_matches_to_schema("in_port=7,eth_type=0x0806");
        assert_eq!(arp.get("arp"), Some(&String::new()));
        assert_eq!(arp.get("in_port"), Some(&"7".to_string()));
        assert_eq!(
            OpenFlowPlugin::switch_actions_to_schema("drop"),
            vec![FlowAction::Drop]
        );
    }

    #[test]
    fn cookie_namespace_and_identity_are_exact() {
        let base = FlowEntry {
            table: 0,
            priority: 100,
            match_fields: HashMap::from([
                ("in_port".to_string(), "7".to_string()),
                ("arp".to_string(), String::new()),
            ]),
            actions: vec![FlowAction::Normal],
            cookie: Some(0x4e4d4b0000000001),
            idle_timeout: 0,
            hard_timeout: 0,
        };
        assert!(OpenFlowPlugin::cookie_in_namespace(
            &base,
            0x4e4d4b0000000000,
            0xffffff0000000000
        ));
        let mut changed_action = base.clone();
        changed_action.actions = vec![FlowAction::Drop];
        assert!(OpenFlowPlugin::same_flow_identity(&base, &changed_action));
        let mut foreign = base;
        foreign.cookie = Some(0xdeadbeef00000001);
        assert!(!OpenFlowPlugin::cookie_in_namespace(
            &foreign,
            0x4e4d4b0000000000,
            0xffffff0000000000
        ));
    }

    #[test]
    fn unknown_live_actions_never_alias_drop() {
        let actions = OpenFlowPlugin::switch_actions_to_schema("write_metadata:0x1/0xff");
        assert_ne!(actions, vec![FlowAction::Drop]);
        assert!(matches!(
            actions.as_slice(),
            [FlowAction::SetField { field, .. }] if field == "__raw_openflow_actions"
        ));
    }
}

