fn field(
    field_type: FieldType,
    required: bool,
    description: &str,
    default: Option<Value>,
    example: Option<Value>,
) -> FieldSchema {
    FieldSchema {
        field_type,
        required,
        description: description.to_string(),
        default,
        example,
        constraints: Vec::new(),
        read_only: false,
        read_only_when: None,
    }
}

