                constraints: Vec::new(),
                read_only: true,
                read_only_when: None,
            },
        );
        fields.insert(
            "netns_pid".to_string(),
            FieldSchema {
                field_type: FieldType::Integer,
                required: false,
                description:
                    "Current container init PID whose network namespace owns the interface"
                        .to_string(),
                default: None,
                example: Some(json!(4242)),
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
