#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn schema_exposes_namespace_aware_mutations() {
        let schema = rtnetlink_schema();
        for method in [
            "move_link",
            "set_link_state",
            "add_ipv4_address",
            "set_default_route",
            "add_route",
        ] {
            assert!(schema.methods.contains_key(method), "missing {method}");
        }
    }

    #[test]
    fn add_route_input_accepts_host_return_route() {
        let input: AddRouteInput = serde_json::from_value(serde_json::json!({
            "destination": "10.200.1.0/30",
            "gateway": "10.200.0.1",
            "interface": "svc0"
        }))
        .unwrap();
        assert_eq!(input.gateway.as_deref(), Some("10.200.0.1"));
        assert_eq!(input.interface, "svc0");
        assert_eq!(input.netns_pid, None);
    }

    #[test]
    fn move_link_requires_explicit_pid() {
        let error = serde_json::from_value::<MoveLinkInput>(serde_json::json!({
            "iface_name": "netmk"
        }))
        .unwrap_err();
        assert!(error.to_string().contains("netns_pid"));
    }
}

//! rovs_commands Plugin — Direct OVSDB Command Execution via D-Bus
//!
//! Schema-only plugin defining callable methods for OVSDB operations.
//! The grpc-bridge exposes these as D-Bus objects at `/org/opdbus/v1/plugins/rovs_commands`
//! that can be called directly via zbus/busctl.
